(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-mx-mixed-precision-dit"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-1\">一 · 一次换分辨率引发的画质塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-2\">二 · 它到底在解决哪一个矛盾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-3\">三 · 共享指数块缩放为什么是这套方案的地基</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-4\">四 · 一个具体的分档与执行例子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-5\">五 · 适用边界的三个硬条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-6\">六 · 失效边界：什么时候这套分档反而会拖慢或画坏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-7\">七 · 校准：逐层敏感度排序与档位落表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-8\">八 · 权重打包：32 元素块共享指数与格式落盘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-9\">九 · 推理前向：按层元数据切换 MMA 精度通路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-10\">十 · 激活在线量化：块级缩放与 outlier 兜底</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-11\">十一 · 末端反量化与送 VAE</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-12\">十二 · 边界条件与失效路径：从校准表到 kernel 分支的逐级代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-13\">十三 · 块缩放公式的逐项解剖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-14\">十四 · 误差上界公式与敏感层指示函数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-15\">十五 · 敏感度排序的伪代码与预算约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-16\">十六 · 推理期格式切换的伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-17\">十七 · 末端反量化与数值稳定性推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-18\">十八 · 公式到系统的闭环判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-19\">十九 · 边界、失效条件与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-20\">二十 · 请求形态：批量 latent 前向是唯一的主场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-21\">二十一 · 长度分布：分辨率与 token 数的分布决定档位是否失配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-22\">二十二 · 并发与批大小：1–8 的窄窗口与显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-23\">二十三 · 负载不对时的三种崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-24\">二十四 · 配方与负载的匹配判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-25\">二十五 · 负载配方：批大小、长度分布与校准覆盖的匹配边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-26\">二十六 · 硬件档位：先定卡型，再定格式上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-27\">二十七 · 并行拓扑：把格式边界对齐到通信边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-28\">二十八 · 量化方案：档位表 + 兜底通道的可复现流程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-29\">二十九 · KV 策略：中间激活缓存的容量与复用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-30\">三十 · 调度参数：batch、段边界与失败模式兜底</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-31\">三十一 · 配方失效的四个断点与代价账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-32\">三十二 · 显存账本：从权重驻留到激活峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-33\">三十三 · 带宽与格式切换：kernel 碎片化的真实代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-34\">三十四 · 通信：张量并行下的格式对齐与集合通信量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-35\">三十五 · 功耗与频率：低精度通路的能效非线性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-36\">三十六 · 尾延迟：小 batch 与分布外提示的双重放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-37\">三十七 · 规模上去以后哪里先崩：拐点排序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-38\">三十八 · 混合精度分块撞上系统墙：从显存账本到尾延迟的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-39\">三十九 · 敏感层被误压到 FP4：校准失配的静默退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-40\">四十 · OOM：激活缓存与批边界的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-41\">四十一 · 批抖动与路由不均：调度层的两类噪声</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-42\">四十二 · 尾延迟尖刺：outlier 溢出与兜底通道</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-43\">四十三 · 监控面与回滚分级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-44\">四十四 · 失效边界：校准失配、kernel 碎片与尾延迟的三类现场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-45\">四十五 · 对照轴：把“选谁”拆成四个可判定维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-46\">四十六 · 决策表：五种相邻路线在同一张表上比较</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-47\">四十七 · 判据伪代码：把选型写成可执行分支</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-48\">四十八 · 具体例子：一条 1024 分辨率服务链的选型推演</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-49\">四十九 · 与统一路线的定量对照：误差项与收益项的分解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-50\">五十 · 工程判断：什么时候不该选 MX 分档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-mixed-precision-dit-sec-51\">五十一 · 边界、失效条件与选型决策</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">校准阶段逐层测敏感度，按输出误差排序分配精度档位</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">权重按 32 元素块做 MX 共享指数缩放，打包为对应格式</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推理时按层元数据选择 MMA 精度通路，敏感层走 FP8</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">激活按块在线量化，累加器统一 FP32</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">末端反量化回 BF16 送 VAE，避免解码漂移</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-mx-mixed-precision-dit-sec-1\">一 · 一次换分辨率引发的画质塌陷</h3>\n<p>某服务化 DiT 集群在 1024×1024 分辨率上完成了 MX 混合精度上线，端到端时延从基线降到原来的六成上下，画质主观评估通过。随后产品侧要求同一模型支持 768×768 与 1280×1280 两种出图尺寸，工程团队按常规做法只改了调度参数与 latent 形状，量化档位沿用了 1024 分辨率校准出来的那份逐层敏感度排序。上线后 1280 分辨率请求的失败率迅速抬升：不是数值溢出报错，而是画面在细节纹理与高频结构上出现明显退化，人脸边缘、织物纹理、文字笔画出现块状涂抹，人工抽检判定为不可交付。回滚到 BF16 后画质恢复，但时延回到基线，SLO 立刻被打穿。</p>\n<p>根因不在 kernel，也不在显存，而在档位分配与当前数据流不匹配。分辨率变化改变了每层激活的统计分布与动态范围，原本在校准集上被判为低敏感、可以压到 MXFP4 的层，在新的 latent 尺度下误差被放大；这些层恰好位于高频重建路径上，误差经后续层逐级放大，最终在 VAE 解码阶段表现为可见的画质塌陷。更麻烦的是，这类退化在单步前向的中间张量统计里并不显著，只有走完整个采样链路、反量化回 BF16 送进 VAE 之后才暴露出来。</p>\n<p>这个事故精确划出了本算法的适用边界：它解决的是“同一模型、同一分辨率、同一提示分布下，如何按层分配 MXFP4/MXFP6/MXFP8 档位，使敏感层不被一刀切压坏、其余层吃满 Blackwell 的 FP4/FP8 吞吐”的问题；它不解决跨分辨率、跨模型、跨提示分布的档位迁移问题——后者必须重跑校准，否则档位失配本身就是新的失败模式。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-2\">二 · 它到底在解决哪一个矛盾</h3>\n<p>DiT 主体的计算量集中在 Transformer 块的 GEMM 上，Blackwell 的 MXFP4 通路能把这类 GEMM 的吞吐推到 FP8 之上，FP8 又显著高于 BF16。统一低精度量化的问题在于，DiT 并非所有层对量化误差同等敏感：注意力投影、条件嵌入注入路径、末端若干块对权重量化误差的容忍度远低于中间 FFN 层。把这些层一并压到 MXFP4，误差在采样链路上累积，画质退化不可控。反过来统一 FP8 或统一 BF16 虽然稳，却把 FP4 那部分吞吐白白让出，算力浪费在不需要高精度的层上。</p>\n<p>于是问题被表述为一个按层分配问题：给定层集合与每层的输出误差敏感度，选择每层的数值格式，使总误差落在可接受范围内、总算力代价最小。形式化地，混合精度下的总误差可写成各层误差的加权和：</p>\n<div class=\"formula\">$$\\text{Err}\\approx\\sum_{l}\\mathbb{1}[l\\in\\text{sens}]\\,\\epsilon_{\\text{FP8}}+\\mathbb{1}[l\\notin\\text{sens}]\\,\\epsilon_{\\text{MXFP4}}$$</div>\n<p>其中 $\\epsilon_{\\text{FP8}}$ 与 $\\epsilon_{\\text{MXFP4}}$ 分别是两种格式在典型层上的量化误差量级，指示函数由校准阶段的敏感度排序决定。这个式子的工程含义很直接：误差预算不是均匀摊到每层，而是集中投在敏感层上；算力预算则相反，尽量把非敏感层推向 FP4。它明确不解决的问题包括：不解决 VAE 解码本身的质量问题（末端反量化回 BF16 只是避免解码漂移，不是提升解码质量）、不解决采样步数与调度器带来的画质上限、也不解决跨模型架构的档位复用。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-3\">三 · 共享指数块缩放为什么是这套方案的地基</h3>\n<p>按层分档要成立，前提是每种格式在各自层上都能稳定表达权重分布。DiT 权重里存在明显的离群通道，per-tensor 量化用一个全局缩放因子时，少数大幅值元素会把整个张量的有效位数吃掉，块内小值被压到零附近。MX 格式的做法是把权重切成 32 元素块，每块共享一个指数：</p>\n<div class=\"formula\">$$w_i=\\hat{w}_i\\cdot 2^{e_{\\text{block}}},\\qquad e_{\\text{block}}=\\max_j \\lfloor \\log_2|w_j|\\rfloor$$</div>\n<p>块内量化尾数 $\\hat{w}_i$ 落在对应格式的尾数位宽内，共享指数 $e_{\\text{block}}$ 只占极小的元数据开销。32 元素这个粒度是关键：块足够小，离群值只污染自己所在的那一块，不会拖累整层；块又足够大，缩放元数据与 kernel 内的格式切换开销被摊薄。相比 per-tensor 量化，块缩放在离群值鲁棒性上有结构性优势，这也是它能支撑“敏感层 FP8、其余 MXFP4”这种激进分档的原因。</p>\n<p>代价体现在 kernel 侧。多格式混合意味着同一个 GEMM 循环里要按层元数据选择不同的 MMA 精度通路，分支变多，编译与调优成本上升；块缩放对极端 outlier 仍可能溢出，工程上需要保留少量 FP8 通道兜底。显存侧则是收益面：低精度权重与按块在线量化的激活让中间激活缓存占用下降，同等显存下可容纳更大 batch，批大小按显存与 SLO 取 1–8 的区间才有腾挪空间。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-4\">四 · 一个具体的分档与执行例子</h3>\n<p>设一个中等规模 DiT，主体含数十个 Transformer 块，每块内有注意力投影与 FFN 两组 GEMM。校准阶段用覆盖目标分辨率与提示分布的校准集跑逐层前向，对每层单独施加 MXFP4 与 FP8 两种量化，测其输出相对 BF16 的误差，按误差排序。排序靠前的若干层——通常是条件注入路径、注意力输出投影、末端块——分配 FP8；其余层分配 MXFP4；介于两者之间的少量层给 MXFP6 作为过渡档。</p>\n<p>打包阶段按 32 元素块计算共享指数、量化尾数，把每层权重写成对应格式并记录层元数据。推理时按元数据逐层选择 MMA 精度通路：敏感层走 FP8 通路，非敏感层走 MXFP4 通路，激活按块在线量化，累加器统一 FP32 以保证跨格式累加的数值一致性，末端反量化回 BF16 再送 VAE。整个链路的时延收益来自非敏感层吃到的 FP4 吞吐，画质可控性来自敏感层的 FP8 保底。按给定事实，整体时延降幅在 30–50% 区间，画质退化可控——注意这个区间是相对统一高精度基线的整体口径，不是单层收益。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>机制</th><th>系统代价</th></tr></thead><tbody><tr><td>校准</td><td>逐层测敏感度、按输出误差排序分档</td><td>一次性离线成本，换模型或换分辨率必须重跑</td></tr><tr><td>打包</td><td>32 元素块共享指数缩放，写对应格式</td><td>元数据开销小，格式种类增多抬高编译复杂度</td></tr><tr><td>推理</td><td>按层元数据切换 MMA 精度通路，FP32 累加</td><td>kernel 分支碎片化，小 batch 下调度开销占比高</td></tr><tr><td>末端</td><td>反量化回 BF16 送 VAE</td><td>避免解码漂移，不改变 VAE 自身算力占比</td></tr></tbody></table>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-5\">五 · 适用边界的三个硬条件</h3>\n<p>第一，负载结构必须是 DiT 主体 GEMM 占主导、VAE 解码占比小的服务化场景。若 VAE 解码在端到端时延中占比可观，主体 GEMM 的精度收益会被稀释，混合精度的复杂度换不回对等的时延下降。第二，校准集必须覆盖目标分辨率与提示分布；分布过窄的校准集会让被判低敏感的层在分布外提示上实际误差放大，块缩放对极端 outlier 失效时引起数值异常，这是事故复现里最隐蔽的一条路径。第三，规模上限受校准成本与 kernel 分支数约束：层数越多，逐层敏感度测量与多格式调优越重，格式种类每增加一档，kernel 内的分支组合就多一层。</p>\n<p>还有一条容易被忽略的边界：多格式 kernel 分支若未充分融合，调度碎片化会让实际吞吐低于理论值，小 batch 下这一开销占比更高。批大小取 1–8 的区间意味着大量请求跑在小 batch 上，此时分支切换的固定开销无法被摊薄，理论上的 FP4 吞吐优势会被吃掉一部分。这不是算法本身的缺陷，而是部署形态与 kernel 工程质量共同决定的实际上限。</p>\n<p>因此判断一个 DiT 服务是否该上这套方案，看的不是“能不能量化”，而是三件事是否同时成立：主体 GEMM 主导时延、校准集能稳定覆盖线上分布、kernel 侧有把多格式分支融合到可接受开销的工程能力。缺任何一条，统一 FP8 或更保守的方案反而是更稳的工程选择。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-6\">六 · 失效边界：什么时候这套分档反而会拖慢或画坏</h3>\n<p>先看一个典型的线上事故形态：服务上线后按统一 NVFP4 压 DiT 主体，单图端到端时延确实好看，但某类高纹理、强边缘的提示词开始出现结构性崩坏——不是随机噪点，而是局部区域整块发灰、细节被抹平。排查发现崩坏集中在少数几个对输出误差最敏感的层，这些层在统一低精度下尾数被截得太狠。反过来把整网抬到 FP8，画质回来了，但 Blackwell 的 FP4 吞吐路径基本闲置，算力浪费在非敏感层上。MX 混合精度分块要解决的正是这个二选一：按层敏感度分配 MXFP4/MXFP6/MXFP8，敏感层保 FP8、其余吃 FP4 吞吐。但它不是万能药，边界必须先划清。</p>\n<p>它不解决的问题有三类。其一，VAE 解码占比高的场景：末端反量化回 BF16 送 VAE 是为了避免解码漂移，可一旦 VAE 本身成为时延主项，主体 GEMM 的精度分档收益被摊薄，整体时延降幅远达不到 30–50% 的量级。其二，校准集覆盖不到的分辨率与提示分布：敏感度排序完全依赖校准阶段逐层测出的输出误差排序，换模型或换分辨率必须重跑，否则档位分配失配，被判低敏感的层被误压到 FP4，画质退化会以分布外提示为触发器突然出现。其三，极端 outlier：32 元素块共享指数让块内动态范围对齐，比 per-tensor 量化稳，但块内若存在远超同伴的离群值，共享指数仍可能把尾数挤到溢出，需要保留少量 FP8 通道兜底，这部分兜底通道本身就是对“全 FP4 吞吐”的折让。</p>\n<div class=\"formula\">$$\\hat{W}_{b}=\\text{shared\\_exp}_{b}\\cdot Q_{p}(W_{b}),\\quad \\text{Err}\\approx\\sum_{l}\\mathbb{1}[l\\in\\text{sens}]\\,\\epsilon_{\\text{FP8}}+\\mathbb{1}[l\\notin\\text{sens}]\\,\\epsilon_{\\text{MXFP4}}$$</div>\n<p>系统代价落在两处，且都在小 batch 下被放大。多格式混合让 kernel 分支变多：同一层元数据要驱动不同 MMA 精度通路，编译与调优成本随格式数与层数上升，层数越多调优越重，规模上限受校准成本与 kernel 分支数双重约束。更隐蔽的是调度碎片化——若多格式分支未融合，实际吞吐低于理论值，批大小取 1–8 时单步前向的固定开销占比更高，分档带来的收益可能被分支切换吃掉。工程判断很直接：只有当 DiT 主体 GEMM 占主导、VAE 解码占比小、且校准集能覆盖目标分辨率与提示分布时，这套按层分档才划算；否则先修校准覆盖面，再谈格式切换。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>分档收益</th><th>主要风险</th></tr></thead><tbody><tr><td>主体 GEMM 主导、VAE 占比小</td><td>敏感层保精度、其余吃 FP4，时延降 30–50%</td><td>分支未融合时吞吐低于理论值</td></tr><tr><td>换模型/换分辨率未重跑校准</td><td>基本失效</td><td>敏感层误压 FP4，画质明显退化</td></tr><tr><td>校准集分布过窄</td><td>分布内正常</td><td>分布外提示触发 outlier 溢出、块缩放失效</td></tr></tbody></table>\n<h3 id=\"alg-mx-mixed-precision-dit-sec-7\">七 · 校准：逐层敏感度排序与档位落表</h3>\n<p>MX 混合精度的第一步不在推理时发生，而在离线校准。对 DiT 的每一层（注意力 QKV 投影、输出投影、FFN 上下投影、以及 patch embed 与最终线性头），在校准集上跑一次 BF16 参考前向，记录该层输出的参考张量，再以候选低精度格式重跑同一层，度量输出误差。误差度量用相对 Frobenius 范数，按层聚合：</p>\n<div class=\"formula\">$$s_{l}=\\frac{\\lVert Y_{l}^{\\text{ref}}-Y_{l}^{\\text{low}}\\rVert_{F}}{\\lVert Y_{l}^{\\text{ref}}\\rVert_{F}+\\varepsilon}$$</div>\n<p>把 $s_l$ 从大到小排序，前若干层落到 MXFP8 档，中间落 MXFP6，其余落 MXFP4。这一步的输入是校准集（必须覆盖目标分辨率与提示分布）、BF16 权重与逐层激活钩子；输出是一张层元数据表，每行记录层名、格式档位、块大小（固定 32 元素）与共享指数位宽。代价是显存与时间：校准需要同时驻留参考激活与低精度重算激活，对 1024×1024 潜空间、批 1–8 的 DiT 主体，单层校准的激活峰值远高于推理稳态，通常要逐层串行、用完即弃，否则显存吃不住。校准本身是一次性成本，但换模型或换分辨率必须重跑——这是本机制最硬的运维约束。</p>\n<p>具体例子：一个 24 层 DiT，校准后排序发现第 0 层 patch embed 与最后两层输出投影的 $s_l$ 明显高于中段 FFN，于是这三层锁 FP8，中段 18 层走 MXFP4，剩余三层走 MXFP6 作为过渡。若跳过重校准直接把 1024 的档位表套到 512 分辨率，patch embed 的输入分布变了，被判低敏感的层实际误差放大，画质退化立刻可见。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-8\">八 · 权重打包：32 元素块共享指数与格式落盘</h3>\n<p>档位确定后进入权重离线打包。对每个权重矩阵按最后一维切成 32 元素块，块内求共享指数：</p>\n<div class=\"formula\">$$w_i=\\hat{w}_i\\cdot 2^{e_{\\text{block}}},\\qquad e_{\\text{block}}=\\max_j \\lfloor \\log_2|w_j|\\rfloor$$</div>\n<p>$\\hat{w}_i$ 是块内量化尾数，$e_{\\text{block}}$ 是 32 元素共享的指数。共享指数把块内动态范围对齐到同一数量级，块内离群值只抬高指数、不撑爆尾数位宽，这正是它比 per-tensor 量化稳的原因：per-tensor 下一个极端 outlier 会把整张矩阵的缩放因子拉偏，其余元素的有效位被白白牺牲。打包输出是「尾数位流 + 每 32 元素一个共享指数」的紧凑布局，MXFP4 每元素 4 位尾数加共享指数开销，MXFP8 每元素 8 位，MXFP6 介于两者之间。</p>\n<p>这一步的代价落在存储与带宽：混合格式意味着权重文件里三种布局并存，加载器要按层元数据分派解析路径，权重加载的 host-to-device 带宽不再是一条均质流，而是按层交错的多段流。工程上要把同格式的层聚在一起连续存放，减少加载时的分支跳转。另一个代价是打包工具链：量化尾数的舍入策略（round-to-nearest 还是随机舍入）会影响敏感层的误差累积，敏感层建议用更保守的舍入并在打包后做一次逐层输出比对，确认与校准阶段的误差量级一致。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-9\">九 · 推理前向：按层元数据切换 MMA 精度通路</h3>\n<p>推理时，DiT 单步前向的每个 GEMM 在发射前读层元数据，决定走哪条 MMA 精度通路。Blackwell 的 tcgen05 MMA 对 MXFP4/MXFP6/MXFP8 有各自的 block scale 硬件路径，敏感层走 FP8 通路，其余层走 FP4 通路，中间档走 FP6。切换发生在 kernel 内部而非 kernel 之间：一个融合的 GEMM 调度器按层号索引格式描述符，把权重指针、共享指数指针、MMA 指令类型一起绑定，避免每层一次 kernel launch 的调度碎片。</p>\n<p>这一步的输入是 BF16 或 FP16 的激活、已打包的低精度权重与层元数据；输出是 FP32 累加的 GEMM 结果。累加器统一 FP32 是关键工程决定：MXFP4 的尾数只有 4 位，若累加也用低精度，块间求和的舍入误差会随 K 维增长迅速累积，FP32 累加把这个误差压到可接受范围。代价体现在两处：其一，FP32 累加器占用 TMEM 与寄存器资源，K 维大时累加器驻留成本可观，限制了单 SM 上能并发的 MMA 数量；其二，多格式分支让 kernel 的指令缓存与寄存器压力上升，编译期要针对每种格式组合生成特化版本，调优成本随格式数线性增长。</p>\n<p>具体例子：注意力块的 QKV 投影若被判敏感走 FP8，其 MMA 吞吐低于 FP4 通路，但这一层在整步前向里占比有限；中段 FFN 的两次大 GEMM 走 MXFP4，是时延下降的主要来源。若把这两次 GEMM 误压到 FP4 而校准显示其敏感，误差会通过残差连乘放大到后续所有层。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-10\">十 · 激活在线量化：块级缩放与 outlier 兜底</h3>\n<p>权重是离线打包的，激活必须在每次前向时在线量化。对每个激活张量按 32 元素块求共享指数，量化到尾数，与权重块缩放同构。在线量化的输入是上一层输出的 BF16 激活，输出是低精度激活加块共享指数，供 MMA 消费。代价是额外的量化 kernel：它读一遍 BF16 激活、写一遍低精度激活与指数，这段带宽开销在激活张量大时不可忽略，尤其在潜空间分辨率高、批较大的配置下，量化 kernel 的访存可能吃掉一部分 GEMM 节省下来的时间。</p>\n<p>outlier 兜底是本步的稳定性核心。块缩放对块内离群值鲁棒，但对跨越多个块的极端 outlier 仍可能溢出——共享指数被抬到高位后，块内其余元素的有效位被压缩到接近零。工程做法是保留少量 FP8 通道：对检测到指数超阈值的块，该块整体降级到 FP8 通路重算，而不是硬塞进 FP4。这个检测在量化 kernel 内做一次比较即可，代价是一条分支和一个阈值常量，但它把数值异常挡在累加器之前。校准集分布过窄时，分布外提示会触发这类溢出，兜底通道是最后一道防线。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-11\">十一 · 末端反量化与送 VAE</h3>\n<p>DiT 主体输出的是潜空间表示，末端必须反量化回 BF16 再送 VAE 解码。反量化按块乘回共享指数，把尾数还原为 BF16 值，累加器里的 FP32 结果先转 BF16 再参与后续的归一化与残差。这一步的输入是 FP32 累加的层输出与块共享指数，输出是 BF16 潜变量。代价很小但位置关键：若省掉这一步、直接把低精度潜变量喂给 VAE，解码器对输入分布的微小偏移极其敏感，颜色漂移与高频伪影会在解码后放大——VAE 解码占比小的服务化场景里，这点开销换的是画质可控。</p>\n<p>工程判断落在批与显存上：低精度权重与激活让显存占用下降，KV（此处指中间激活缓存）随之缩小，于是批大小可以按显存与 SLO 往上取到 1–8 的上沿。批增大摊薄了逐层格式切换与小 batch 下的调度开销——多格式 kernel 分支未融合时，小 batch 下分支开销占比更高，实际吞吐低于理论值；批上去之后 GEMM 占主导，分支被摊薄，30–50% 的时延降幅才落得下来。反过来，若 SLO 以单图端到端时延计且批只能取 1，格式切换的固定开销就会咬住收益，此时应优先融合同格式相邻层、减少分支数，而不是继续压精度档位。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-12\">十二 · 边界条件与失效路径：从校准表到 kernel 分支的逐级代价</h3>\n\n<p>把混合精度分块落到 DiT 推理链路上，代价并不集中在某一层，而是沿着“校准表 → 权重打包 → 层元数据 → kernel 分支 → 末端反量化”逐级累积。校准阶段逐层测敏感度、按输出误差排序分配 MXFP4/MXFP6/MXFP8 档位，这一步的输入是覆盖目标分辨率与提示分布的校准集，输出是一张层号到格式的映射表；代价是离线一次性开销，但它决定了后续所有在线路径的形状。权重按 32 元素块做 MX 共享指数缩放并打包为对应格式，输入是 BF16 权重，输出是“尾数 + 共享指数”的紧凑布局，代价体现在打包后的显存占用与加载时的解包指令数——块越小，元数据占比越高，32 元素块意味着每块一个指数，元数据开销被压到可接受区间，但对极端 outlier 仍可能溢出，因此需保留少量 FP8 通道兜底。推理时按层元数据选择 MMA 精度通路，敏感层走 FP8、其余走 MXFP4，激活按块在线量化、累加器统一 FP32，末端反量化回 BF16 送 VAE 以避免解码漂移。这条链上每一环都有明确的失效条件：校准表失配、kernel 分支未融合、分布外提示触发溢出。</p>\n\n<p>第一类失效来自校准表的时效性。敏感度排序依赖校准集，换模型或换分辨率必须重跑，否则档位分配失配——被判低敏感的层在真实负载下误差放大，被误压到 FP4 后画质明显退化。这里的系统代价不是算力而是返工：校准成本随层数线性增长，层数越多调优越重，规模上限正受此约束。第二类失效来自 kernel 碎片化。多格式混合让 kernel 分支变多，编译与调优成本高；若分支未融合，调度碎片化使实际吞吐低于理论值，且小 batch 下开销占比更高——DiT 单步前向的批量 latent 生成批大小按显存与 SLO 取 1–8，小 batch 恰恰是服务化常态，分支切换的固定开销无法被摊薄。第三类失效来自分布外提示：校准集分布过窄时，outlier 溢出使块缩放失效，引起数值异常。块缩放对离群值比 per-tensor 量化更鲁棒，但鲁棒不等于免疫，共享指数一旦被单个极端值拉高，块内其余元素的尾数有效位被压缩，等效精度下降。</p>\n\n<div class=\"formula\">$$\\text{Err}\\approx\\sum_{l}\\mathbb{1}[l\\in\\text{sens}]\\,\\epsilon_{\\text{FP8}}+\\mathbb{1}[l\\notin\\text{sens}]\\,\\epsilon_{\\text{MXFP4}},\\qquad w_i=\\hat{w}_i\\cdot 2^{e_{\\text{block}}},\\; e_{\\text{block}}=\\max_j \\lfloor \\log_2|w_j|\\rfloor$$</div>\n\n<p>上式给出两个工程判断点。其一，总误差是逐层误差的加权和，敏感层集合的判定直接决定误差上界；一旦某敏感层被错分到 MXFP4，其 $\\epsilon_{\\text{MXFP4}}$ 会整层进入求和，无法被其他层的低误差抵消。其二，共享指数取块内最大幅值的对数下取整，意味着块内动态范围由最坏元素支配——这是 MX 格式对离群值鲁棒的来源，也是其精度天花板的来源。工程上应把这两点转化为可执行的检查项：校准表需绑定模型版本与分辨率并纳入发布流程，换分辨率即触发重跑；层元数据在加载时做一致性校验，防止旧表配新权重；对判定为敏感但校准置信度不足的层，默认降级到 FP8 而非 MXFP4，用少量吞吐换稳定性。适用边界也由此清晰：该方案适合 DiT 主体 GEMM 占主导、VAE 解码占比小的服务化场景，因为末端反量化回 BF16 送 VAE 的开销在整图时延中占比有限；若 VAE 解码占比上升，反量化与格式切换的固定成本会被放大，混合精度的收益被稀释。整体时延降 30–50% 的前提是分支已融合、校准表匹配当前负载，两个条件任一不满足，实测吞吐就会落在理论值之下。</p>\n\n<table class=\"mini\"><thead><tr><th>环节</th><th>输入 → 输出</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>校准排序</td><td>校准集 → 层号-格式表</td><td>离线一次性，随层数线性增长</td><td>换模型/分辨率未重跑</td></tr><tr><td>权重打包</td><td>BF16 权重 → 尾数+共享指数</td><td>元数据占比、解包指令</td><td>极端 outlier 溢出</td></tr><tr><td>MMA 选路</td><td>层元数据 → 精度通路</td><td>分支切换固定开销</td><td>分支未融合、小 batch</td></tr><tr><td>末端反量化</td><td>FP32 累加 → BF16 送 VAE</td><td>整图时延占比</td><td>VAE 占比上升稀释收益</td></tr></tbody></table>\n\n<p>把上表落到调度层，还有一个容易被忽略的代价：低精度后中间激活缓存显存占用下降，可容纳更大 batch，但批大小仍受 SLO 约束——SLO 以单图端到端时延计，扩大 batch 会拉长单图时延，二者在 1–8 的区间内互相挤压。真正的工程判断是：混合精度的吞吐收益来自 GEMM 通路的格式选择，而非 batch 放大；把 batch 放大当作主要手段，会在小 batch 服务形态下失效。因此部署配方应以单卡为主、大模型走张量并行，把格式切换的调度开销控制在单卡内，避免跨卡同步放大分支碎片化的影响。</p>\n<h3 id=\"alg-mx-mixed-precision-dit-sec-13\">十三 · 块缩放公式的逐项解剖</h3>\n<p>MX 混合精度的数值核心只有一条式子，但它决定了后面所有 kernel 行为：</p>\n<div class=\"formula\">$$w_i=\\hat{w}_i\\cdot 2^{e_{\\text{block}}},\\qquad e_{\\text{block}}=\\max_j \\lfloor \\log_2|w_j|\\rfloor$$</div>\n<p>逐项看。$w_i$ 是块内第 $i$ 个原始权重（BF16 或 FP32 校准态）；$\\hat{w}_i$ 是量化后的尾数，落进 MXFP4/MXFP6/MXFP8 各自的尾数位宽；$e_{\\text{block}}$ 是 32 个元素共享的指数。关键在于 $e_{\\text{block}}$ 取的是块内绝对值最大元素的向下取整二进制对数——这一步把整块的动态范围“对齐”到同一个指数栅格上，块内元素只在这个栅格内用尾数表达相对大小。推导的关键一步在于：若改用 per-tensor 缩放，$e$ 由全张量最大值决定，一个离群通道就会把其余元素的尾数挤到几乎为零的有效位；而把 $e$ 的作用域缩到 32 元素，离群值只污染自己所在的那一块，其余块的尾数位宽被完整保留。这就是“对离群值鲁棒”的数学来源，不是工程玄学。</p>\n<p>代价直接体现在硬件通路上：共享指数意味着每 32 元素需要一个额外的 scale 字段随数据同行，Blackwell 的 block-scale 硬件路径正是为此设计，但 scale 元数据本身占带宽。以 MXFP4 为例，32 个元素占 16 字节，外加一个 8 位指数，元数据开销约 6%；若块缩到 16 元素，开销翻倍而鲁棒性增益递减，32 是硬件与精度的折中点。举例：某层权重某块内出现一个幅值为其余元素 64 倍的离群通道，per-tensor 下其余元素只剩约 1/64 的相对幅度、尾数几乎全零；32 元素块缩放下，该离群值独占一块的指数，相邻块照常量化，误差被局部封死。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-14\">十四 · 误差上界公式与敏感层指示函数</h3>\n<p>混合格式的总误差写成按层求和的形式：</p>\n<div class=\"formula\">$$\\text{Err}\\approx\\sum_{l}\\mathbb{1}[l\\in\\text{sens}]\\,\\epsilon_{\\text{FP8}}+\\mathbb{1}[l\\notin\\text{sens}]\\,\\epsilon_{\\text{MXFP4}}$$</div>\n<p>$\\mathbb{1}[\\cdot]$ 是指示函数，$\\text{sens}$ 是校准阶段判定的敏感层集合，$\\epsilon_{\\text{FP8}}$ 与 $\\epsilon_{\\text{MXFP4}}$ 分别是两种格式在单层上的量化误差贡献。这个式子的推导要点不在求和，而在“误差可加性假设”：它假定层间误差近似独立叠加、不出现跨层放大。对 DiT 这种残差主干 + 注意力混合的结构，该假设在敏感层被保住 FP8 后基本成立——因为放大误差的通常是少数几层（末端投影、与 VAE 解码耦合的输出侧层），把它们从 MXFP4 提到 FP8，等于把求和里系数最大的那几项换成了小量。</p>\n<p>工程含义：这个公式给出的是“分配问题”的目标函数，而不是可闭式求解的表达式。校准阶段实际做的是逐层扰动、测输出误差、按误差排序，把误差最大的若干层塞进 $\\text{sens}$，直到预算（FP8 层的比例）用完。代价在于校准本身：每层一次前向扰动、覆盖目标分辨率与提示分布，层数越多校准越贵；换模型或换分辨率必须重跑，否则 $\\text{sens}$ 失配，指示函数把敏感层误判进 MXFP4 分支，画质退化立刻可见。举例：换到更高分辨率后，注意力输出投影的误差权重上升，若沿用旧排序，该层仍走 MXFP4，误差项 $\\epsilon_{\\text{MXFP4}}$ 被放大而非被 $\\epsilon_{\\text{FP8}}$ 替换。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-15\">十五 · 敏感度排序的伪代码与预算约束</h3>\n<p>把上面的目标函数落成可执行流程，核心是一个带预算的排序循环：</p>\n<ul>\n<li>对每层 $l$：临时把该层权重压到候选低精度格式，跑一次校准前向，记录输出与 BF16 参考的误差 $\\delta_l$；</li>\n<li>按 $\\delta_l$ 降序排序，得到敏感度序列；</li>\n<li>从序列头部开始分配 FP8，直到 FP8 层数占比触及预算上限 $B$（由吞吐目标反推）；</li>\n<li>其余层分配 MXFP4，中间档 MXFP6 留给误差处于中位、又不想付 FP8 带宽的层；</li>\n<li>写回每层元数据：格式枚举 + 块缩放指数表。</li>\n</ul>\n<p>预算 $B$ 是精度与吞吐的旋钮。FP8 层的 MMA 吞吐低于 MXFP4 通路，$B$ 越大越稳越慢；$B$ 越小越吃 FP4 吞吐但误差项抬头。伪代码里必须显式处理的一个细节是：排序用的 $\\delta_l$ 是单层扰动误差，而实际部署是全体混合，层间存在轻微耦合，因此分配后要跑一次整网校验前向，若端到端误差超阈值则回退序列中下一层到 FP8。这一步是纯工程兜底，公式给不了。</p>\n<p>系统代价：校准循环的前向次数与层数成正比，且每次都要在目标分辨率上跑，显存峰值出现在参考输出与扰动输出同时驻留时；对单卡部署，这意味着校准阶段 batch 必须压到很小，与推理阶段的 1–8 批配方是两套配置。举例：一个含数十个 GEMM 层的 DiT 主干，校准需逐层扰动数十次前向，若每次都在高分辨率 latent 上跑，校准耗时可达推理单步的数十倍——这是一次性成本，但换分辨率就要重付。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-16\">十六 · 推理期格式切换的伪代码</h3>\n<p>推理侧的可实现骨架按层元数据分派，累加器统一 FP32：</p>\n<ul>\n<li>读层元数据 $\\rightarrow$ 取格式枚举与块指数表；</li>\n<li>权重已按 32 元素块打包为对应格式，直接送入对应 MMA 通路；</li>\n<li>激活按块在线量化：先求块内最大幅值、取共享指数、再量化尾数，与权重同栅格对齐；</li>\n<li>MMA 累加进 FP32 累加器，不在低精度里做归约；</li>\n<li>末端反量化回 BF16，送 VAE 解码，避免解码端漂移。</li>\n</ul>\n<p>关键一步是激活的在线块量化必须与权重的块边界对齐，否则同一个 MMA 指令里权重块与激活块的共享指数作用域不一致，缩放因子无法在指令内合并。对齐后，指令内只需一次指数合并即可完成块缩放乘法。累加器保 FP32 的理由是：MXFP4 尾数位宽窄，若在低精度累加，长 K 维归约的舍入误差会累积成可见偏差，而 FP32 累加在 Blackwell 的 MMA 通路上是原生支持的，不额外付吞吐。</p>\n<p>系统代价落在 kernel 分支上：多格式混合意味着同一份 kernel 要按层元数据走不同 MMA 精度通路，分支增多带来编译组合爆炸与调度碎片化。小 batch 下这种开销占比更高——批大小为 1 时，每次格式切换的固定开销摊不到足够多的 tile 上，实际吞吐可能低于理论值。举例：敏感层走 FP8、非敏感层走 MXFP4 的交替结构，若相邻两层格式不同且未融合，kernel 启动与元数据加载的间隙会打断流水，此时把同格式的相邻层聚成组、按组调度可显著减少切换次数。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-17\">十七 · 末端反量化与数值稳定性推导</h3>\n<p>末端反量化不是礼节性步骤，它有明确的误差动机。设 DiT 主干输出为 $\\hat{y}$（低精度计算后已反量化回 BF16），VAE 解码器对输入的微小扰动敏感，尤其在潜空间一致性要求高的采样器下。若把低精度累加结果直接以低精度送入 VAE，解码端的非线性层会放大尾数截断误差，表现为色彩偏移或纹理漂移。反量化回 BF16 把误差限制在主干输出端，不让它穿过解码器。</p>\n<p>稳定性还有一条兜底：块缩放对极端 outlier 仍可能溢出——当某块内最大幅值超出格式指数范围时，$e_{\\text{block}}$ 被截断，尾数饱和。工程做法是保留少量 FP8 通道作为兜底，即对校准中反复触发饱和的块，把该块所在层整体提到 FP8，而不是逐块混格式（逐块混格式会让 kernel 分支进一步碎片化）。这与敏感层分配是同一套元数据机制，只是触发条件从“层误差排序”换成“块饱和计数”。</p>\n<p>代价：反量化本身是一次全量元素级操作，输出张量规模与 latent 同阶，在单图端到端时延里占比小但不可忽略；兜底 FP8 通道会拉低该层的 FP4 吞吐收益，属于用少量吞吐换数值确定性。举例：某层在分布外提示下出现块饱和，若不兜底，反量化后数值异常会在 VAE 解码端放大成可见伪影；兜底后该层走 FP8，吞吐略降但输出稳定。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-18\">十八 · 公式到系统的闭环判断</h3>\n<p>把三组式子串起来看，MX 混合精度分块的可实现性取决于三个闭环是否闭合：块缩放公式闭环于硬件 block-scale 通路，误差上界公式闭环于校准排序与预算 $B$，推理伪代码闭环于元数据驱动的格式分派与 FP32 累加。任一环断开，公式再漂亮也落不了地——校准集分布过窄会让 $\\text{sens}$ 失真，kernel 分支未融合会让理论吞吐打折，块饱和未兜底会让数值异常穿透到解码端。</p>\n<p>工程判断上，这套方法的收益边界由“DiT 主体 GEMM 占比”划定：主体 GEMM 占主导时，按层分档能把大部分计算压到 MXFP4 通路，敏感层付 FP8 的少量代价，整体时延收益落在给定事实的 30–50% 区间；VAE 解码占比上升时，末端反量化与解码本身成为时延主项，混合精度的边际收益递减。规模上限则受校准成本与 kernel 分支数双重约束：层数越多，排序与调优越重，分支组合越难收敛。因此部署时的具体动作是——先固定分辨率与提示分布跑校准、锁定 $\\text{sens}$ 与预算 $B$，再把同格式相邻层聚组以减少切换，最后用整网校验前向确认端到端误差未越阈值，三者都过才把元数据固化进服务镜像。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-19\">十九 · 边界、失效条件与系统代价</h3>\n<p>该方案的精度收益并非无条件成立。核心公式 $\\hat{W}_{b}=\\text{shared\\_exp}_{b}\\cdot Q_{p}(W_{b})$ 中，$Q_{p}$ 的档位选择由校准阶段逐层测得的输出误差排序决定，因此整个精度保证是<strong>相对校准分布</strong>的。一旦换模型或换分辨率而未重跑敏感度排序，原本被判为低敏感的层可能被误压到 MXFP4，此时误差项 $\\text{Err}\\approx\\sum_{l}\\mathbb{1}[l\\in\\text{sens}]\\,\\epsilon_{\\text{FP8}}+\\mathbb{1}[l\\notin\\text{sens}]\\,\\epsilon_{\\text{MXFP4}}$ 中的指示函数整体失配，画质退化会以块状伪影的形式集中出现在被误判的层上。校准集分布过窄是同一失效链的另一端：分布外提示触发 outlier 时，32 元素共享指数 $e_{\\text{block}}=\\max_j\\lfloor\\log_2|w_j|\\rfloor$ 被单个极端值拉高，块内其余尾数的有效位被压缩，块缩放对离群值的鲁棒性在此让位于溢出风险，需保留少量 FP8 通道兜底。</p>\n<p>系统代价集中在 kernel 侧。多格式混合意味着同一前向图中存在多条 MMA 精度通路，按层元数据切换格式使分支数随精度档位数增长，编译与调优成本随之上升；若分支未融合，调度碎片化会让实际吞吐低于理论值，且小 batch 下开销占比更高——而 DiT 单步前向的批大小按显存与 SLO 只取 1–8，恰好落在碎片化最敏感区间。下表给出代价的定性对照：</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>统一 FP8</th><th>MX 混合分档</th></tr></thead><tbody><tr><td>敏感层误差</td><td>受 $\\epsilon_{\\text{FP8}}$ 约束</td><td>敏感层保 FP8，非敏感层吃 FP4 吞吐</td></tr><tr><td>kernel 分支</td><td>单通路</td><td>多通路，编译调优成本高</td></tr><tr><td>校准依赖</td><td>无</td><td>换模型/分辨率必须重跑</td></tr><tr><td>显存</td><td>基准</td><td>低精度层激活缓存下降，可容纳更大 batch</td></tr></tbody></table>\n<p>适用边界由此清晰：该方案适合 DiT 主体 GEMM 占主导、VAE 解码占比小的服务化场景，末端反量化回 BF16 送 VAE 正是为避免解码漂移而设的固定开销；规模上限受校准成本与 kernel 分支数双重约束，层数越多调优越重。工程判断上，是否启用应看两个量：敏感层占比决定 FP8 通路保留多少算力，分支融合程度决定理论吞吐能否兑现；前者靠校准集覆盖度保证，后者靠 kernel 内格式切换的实现质量保证，二者任一不达标，30–50% 的时延收益就会被碎片化开销吃掉。</p>\n<h3 id=\"alg-mx-mixed-precision-dit-sec-20\">二十 · 请求形态：批量 latent 前向是唯一的主场</h3>\n<p>MX 混合精度分块的收益结构决定了它只对一种请求形态友好：以 DiT 主体 GEMM 为主导的批量 latent 前向。这类请求的算力构成里，主干 Transformer 块的 QKV 投影、注意力输出投影、FFN 两层占据绝大部分 FLOPs，VAE 解码只占尾部一小段。混合格式把敏感层钉在 FP8、其余层压到 MXFP4，省下来的正是主干那部分时间；末端反量化回 BF16 送 VAE 的那一段并不因量化而缩短，反而因为多一次格式转换略有增加。于是收益与“主干占比”成正比，与“解码占比”成反比。</p>\n<p>请求形态的另一面是批的构成。DiT 单步前向天然是批量 latent 生成：一个 batch 内 N 个 latent 共享同一套权重、同一组层元数据，逐层走同一条 MMA 精度通路。这带来一个关键性质——格式切换发生在层边界，而不是样本边界。只要整批走同一层，kernel 内分支的代价就被 N 个样本摊薄。反之，若请求形态是逐样本异构的（不同分辨率、不同采样步数混在同一批里），层元数据无法统一，混合精度通路要么退化为最保守档位，要么被迫拆批，摊薄效应消失。</p>\n<p>因此判断一个服务是否适合上这套方案，第一问不是“模型多大”，而是“主干 GEMM 时间占比多少、批内是否同构”。主干占比高且批内同构，配方成立；主干占比低或批内异构，配方带来的 30–50% 时延下降会被尾部开销与拆批损失吃掉大半。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-21\">二十一 · 长度分布：分辨率与 token 数的分布决定档位是否失配</h3>\n<p>扩散模型的“长度”不是文本序列长度，而是 latent 网格的空间尺寸经 patchify 后的 token 数。分辨率翻倍，token 数约翻四倍，注意力与 GEMM 的规模同步抬升，激活的数值分布也随之改变——更高分辨率下高频细节更多，激活 outlier 的位置与幅度都会漂移。敏感度排序是在特定分辨率校准集上测出来的，档位分配与 token 长度分布强耦合。</p>\n<p>设服务实际收到的分辨率分布为 $p(r)$，校准集覆盖的分辨率集合为 $R_c$，则档位失配的风险可以写成一个覆盖度判据：</p>\n<div class=\"formula\">$$\\text{MisMatch}\\propto\\sum_{r\\notin R_c}p(r)\\cdot\\frac{\\|\\Delta_{l}(r)\\|}{\\|\\Delta_{l}(r_c)\\|}$$</div>\n<p>其中 $\\Delta_l$ 是第 $l$ 层在给定分辨率下的输出误差相对校准点的偏移。这个式子不要求精确数值，它表达的是工程判断：分布外分辨率的请求占比越高、偏移越大，被判为低敏感的层就越可能在真实负载上放大误差。表现是画质退化集中在特定分辨率档，而不是全局均匀变差——这恰恰是最难排查的一类退化。</p>\n<p>长度分布还影响批的打包效率。token 数差异大的请求若强行同批，padding 会浪费算力；若按长度分桶，桶内批大小又被压小，摊薄效应减弱。工程上通常按分辨率分桶、桶内定批，把“同构”做实，代价是调度器多一层桶管理逻辑。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-22\">二十二 · 并发与批大小：1–8 的窄窗口与显存账</h3>\n<p>批大小按显存与 SLO 取 1–8，这个窄窗口不是随意定的。低精度后权重与中间激活的显存占用下降，理论上可以容纳更大 batch，但 DiT 单图端到端时延的 SLO 约束把批大小锁死：批越大，单批完成时间越长，尾延迟越难满足。真正的显存账要算三块——权重（按层混合格式打包，MXFP4 层每 32 元素块带一个共享指数，额外开销是块数×指数位宽）、中间激活缓存（低精度在线量化后按块存储，累加器仍占 FP32）、以及 kernel 工作区。</p>\n<p>并发上升时，批大小与并发数的乘积决定在飞请求数。混合格式的 kernel 分支变多，每个分支有自己的启动开销与占用寄存器/共享内存的配置，小 batch 下这部分固定开销占比更高。设单层混合通路的固定开销为 $c_f$、随批增长的算力项为 $c_b\\cdot B$，则有效吞吐近似为：</p>\n<div class=\"formula\">$$\\text{Throughput}(B)\\approx\\frac{B}{c_f+c_b\\cdot B}\\quad\\Rightarrow\\quad \\text{小 }B\\text{ 时被 }c_f\\text{ 主导}$$</div>\n<p>这条曲线的含义很直接：批大小从 1 抬到 2 的边际收益远大于从 4 抬到 8，而超过某个点后尾延迟先崩。所以配方的实际形态是“小批、多并发副本”，用副本数而非批大小去填满 GPU。这也解释了为什么多格式 kernel 分支未融合时，小 batch 场景的实际吞吐明显低于理论值——固定开销摊不掉。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-23\">二十三 · 负载不对时的三种崩法</h3>\n<p>第一种是校准失配。换模型或换分辨率未重跑敏感度排序，档位分配沿用旧表，敏感层被误压到 MXFP4。公式里的误差项 $\\mathbb{1}[l\\in\\text{sens}]\\,\\epsilon_{\\text{FP8}}+\\mathbb{1}[l\\notin\\text{sens}]\\,\\epsilon_{\\text{MXFP4}}$ 会因 $\\text{sens}$ 集合判错而整体偏移，画质退化表现为结构性伪影而非均匀噪声。这类失败在离线评测里可能被平均指标掩盖，上线后在特定提示上集中爆发。</p>\n<p>第二种是调度碎片化。多格式混合让 kernel 分支变多，若分支未融合，逐层切换格式产生流水线气泡，实际吞吐低于理论值。负载越轻、批越小，气泡占比越高，30–50% 的时延收益可能被蚕食到个位数。工程对策是把相邻同格式层合并成连续段、减少切换点，代价是敏感度排序的自由度下降——这是一个明确的取舍，不是免费的优化。</p>\n<p>第三种是分布外 outlier 溢出。校准集分布过窄时，真实请求触发块内极端离群值，共享指数 $e_{\\text{block}}=\\max_j\\lfloor\\log_2|w_j|\\rfloor$ 被拉到很大，块内其余元素的尾数精度被压缩，块缩放失效引起数值异常。兜底手段是保留少量 FP8 通道，在检测到块内动态范围超阈值时切回高精度通路——这又回到 kernel 分支成本上，形成闭环。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-24\">二十四 · 配方与负载的匹配判据</h3>\n<p>把上述几条收束成可执行的判据。第一，主干 GEMM 时间占比高于 VAE 解码占比，且批内请求同构——不满足则收益结构不成立。第二，实际分辨率分布被校准集覆盖，或至少分布外占比低到可接受；换分辨率必须重跑敏感度排序，这是硬约束而非建议。第三，批大小落在 1–8 且以副本数扩并发，而不是靠抬批填 GPU；小 batch 下必须确认 kernel 分支已融合，否则固定开销吃掉收益。第四，保留 FP8 兜底通道应对 outlier，并接受它带来的分支碎片化。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>配方适配</th><th>失配后果</th></tr></thead><tbody><tr><td>主干 GEMM 主导、批内同构</td><td>成立，摊薄充分</td><td>—</td></tr><tr><td>VAE 解码占比高</td><td>收益被尾部抵消</td><td>时延下降远小于 30–50%</td></tr><tr><td>分辨率分布外</td><td>需重跑校准</td><td>敏感层误压，结构性伪影</td></tr><tr><td>批大小 &lt; 2 且分支未融合</td><td>固定开销主导</td><td>吞吐低于理论值</td></tr><tr><td>校准集过窄</td><td>需 FP8 兜底</td><td>块缩放失效，数值异常</td></tr></tbody></table>\n<p>这张表的价值在于把“适合什么负载”从定性描述变成逐项可核对的清单。工程上真正决定成败的往往不是量化格式本身，而是负载与配方的这几次对齐：分辨率对齐、批同构对齐、分支融合对齐。任何一项错位，混合精度分块的优势都会从“时延降 30–50%”退化为“画质退化可控但速度没赚到”，而后者在服务化场景里等于白做。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-25\">二十五 · 负载配方：批大小、长度分布与校准覆盖的匹配边界</h3>\n<p>这套按层混合精度的收益并非无条件成立，它的负载画像相当窄：请求形态必须是 DiT 单步前向的批量 latent 生成，批大小按显存与 SLO 在 1–8 之间取，SLO 以单图端到端时延计。原因在于收益结构——敏感层走 FP8、其余层吃 MXFP4 吞吐，省下的是主体 GEMM 的时间；而末端反量化回 BF16 送 VAE 这一段是固定的、不可压缩的开销。设单步总时延为 <span class=\"formula\">$$T_{\\text{step}}=T_{\\text{GEMM}}^{\\text{mix}}+T_{\\text{quant}}+T_{\\text{dequant}}+T_{\\text{VAE}}$$</span>，其中只有第一项随格式分档下降 30–50%，后三项与精度档位基本无关。因此当 VAE 解码占比升高（高分辨率、少步数采样、或 batch 很小导致 GEMM 未打满）时，端到端时延的改善会被稀释；反过来，DiT 主体 GEMM 占主导的服务化场景才是它的甜点区。批大小 1–8 的约束同样来自这条式子：低精度后中间激活缓存（KV 指中间激活缓存）显存占用下降，本可容纳更大 batch，但 batch 增大到一定程度后 kernel 分支切换的固定开销被摊薄、收益趋稳，而 SLO 以单图时延计时，大 batch 反而拉长尾延迟。</p>\n<p>长度分布与分辨率分布是第二个失效面。敏感度排序依赖校准集，而校准集必须覆盖目标分辨率与提示分布；换模型或换分辨率必须重跑排序，否则档位分配失配——被判低敏感的层被误压到 MXFP4，画质明显退化。这不是偶发噪声，而是系统性错配：分辨率改变会改变各层激活的动态范围与离群值位置，原先的 32 元素块共享指数 <span class=\"formula\">$$e_{\\text{block}}=\\max_j \\lfloor \\log_2|w_j|\\rfloor$$</span> 在新的分布下可能把整块尾数压到过窄的表示区间。校准集分布过窄时，分布外提示触发 outlier 溢出，块缩放失效引起数值异常，此时需要保留少量 FP8 通道兜底。工程判断是：把校准集当作与分辨率、提示模板、采样步数绑定的“配置项”管理，任何一项变更都触发重跑，而不是当成一次性离线产物。</p>\n<p>并发形态上，这套方案对连续批处理与请求混合度的容忍度低于统一精度方案。多格式混合让 kernel 分支变多，编译与调优成本高；若多格式 kernel 未融合，调度碎片化使实际吞吐低于理论值，且小 batch 下开销占比更高——因为分支切换的固定成本无法被大批次的 GEMM 摊薄。这与分离式预填/解码的调度逻辑相冲突：预填阶段大批量、解码阶段小批量的节奏切换，会让按层格式切换的分支预测与 kernel 选择反复失效。可行的配方是把 batch 控制在 1–8 的窄区间、避免同一批次内混入差异过大的分辨率，让每次前向的层格式序列保持稳定，从而让 kernel 选择退化为一次元数据查表而非运行时决策。</p>\n<table class=\"mini\"><thead><tr><th>负载条件</th><th>收益表现</th><th>主要代价</th></tr></thead><tbody><tr><td>DiT GEMM 主导、VAE 占比小、batch 1–8</td><td>时延降 30–50%，画质退化可控</td><td>kernel 分支调优成本</td></tr><tr><td>高分辨率、少步采样、VAE 占比升高</td><td>端到端改善被稀释</td><td>反量化与 VAE 固定开销</td></tr><tr><td>换分辨率/换模型未重跑校准</td><td>档位失配，敏感层误压 FP4</td><td>画质明显退化</td></tr><tr><td>小 batch + 未融合多格式 kernel</td><td>吞吐低于理论值</td><td>调度碎片化开销占比高</td></tr></tbody></table>\n<p>规模上限由校准成本与 kernel 分支数共同约束：层数越多，逐层敏感度测量与调优越重，格式档位（MXFP4/MXFP6/MXFP8）的组合空间随层数线性膨胀，而每个新增分支都要在编译期与运行期各付一次代价。因此这套配方适合层结构稳定、分辨率集合有限、以单卡为主（大模型走张量并行）的部署；对分辨率连续可变、提示分布开放、或需要频繁换模型的服务，统一 FP8 或统一 NVFP4 的粗粒度方案在工程上更可控——它牺牲了敏感层的精度保留，但换来了无分支的 kernel 与一次性的校准。判断标准很具体：当校准重跑频率高于模型迭代频率时，按层分档的边际收益已被调优成本吃掉。</p>\n<h3 id=\"alg-mx-mixed-precision-dit-sec-26\">二十六 · 硬件档位：先定卡型，再定格式上限</h3>\n<p>部署配方第一步不是选框架，而是把硬件档位与格式上限锁死。Blackwell 的 MX 路径依赖 block scale 硬件通路：SM100 上 MXFP8 的 MMA 吞吐高于 MXFP6，MXFP6 又高于 MXFP4，但三者的指令发射与累加器行为一致，差别只在每周期搬运的尾数位宽与缩放因子解析开销。工程上应把档位分成三档：单卡 B200/B300 面向单图低延迟，格式上限放到 MXFP4；GB200/GB300 NVL72 单柜面向高吞吐批服务，格式上限同样到 MXFP4 但必须预留 FP8 兜底通道；张量并行跨卡档位则把格式上限压到 MXFP8，因为跨卡 all-reduce 的激活是 BF16/FP8 混合，再压到 FP4 会让通信量与反量化次数同时上升，抵消算力收益。</p>\n<p>判断依据是一条简单的收益不等式：设某层在格式 <span>f</span> 下的单次 MMA 时间为 <span>t_f</span>，反量化与格式切换开销为 <span>c_f</span>，则该层净收益为 <span>t_BF16 − (t_f + c_f)</span>。当 <span>c_f</span> 随 kernel 分支数增长时，小 batch 下 <span>c_f</span> 占比被放大——这是失败模式里“调度碎片化使实际吞吐低于理论值”的量化来源。因此硬件档位表必须同时标注 batch 下限：单卡档建议 batch ≥ 2 才启用 MXFP4 主体，batch = 1 时把敏感层之外的中间层退回 MXFP8，用格式统一换调度连续性。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>拓扑</th><th>格式上限</th><th>batch 下限</th><th>主要代价</th></tr></thead><tbody><tr><td>单卡低延迟</td><td>1×B200/B300</td><td>MXFP4 + FP8 兜底</td><td>2</td><td>kernel 分支碎片</td></tr><tr><td>单柜高吞吐</td><td>NVL72 内多卡 TP</td><td>MXFP4（跨卡段 MXFP8）</td><td>4</td><td>all-reduce 带宽</td></tr><tr><td>跨卡大模型</td><td>TP=2/4/8</td><td>MXFP8</td><td>按 SLO 反推</td><td>反量化次数、通信</td></tr></tbody></table>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-27\">二十七 · 并行拓扑：把格式边界对齐到通信边界</h3>\n<p>DiT 主体的 GEMM 占主导，张量并行是最自然的切法，但切分点必须与格式边界重合。做法是：先按敏感度排序得到层档位序列，再把 TP 切分点放在“档位变化处”而非均匀层数处。这样每个 rank 内部的格式集合一致，kernel 只需编译一次分支组合，避免同一 rank 上 MXFP4 与 MXFP8 交替导致的指令缓存抖动。对于 NVL72 档位，注意力段的 TP 组与 FFN 段的 TP 组可以不同宽——注意力用较窄 TP 保低延迟，FFN 用较宽 TP 吃吞吐，两组之间用一次 BF16 重分布衔接。</p>\n<p>通信代价要显式计入配方：TP 组内每层一次 all-reduce，激活若已是 FP8，通信量为 BF16 的一半；若强行把跨卡激活压到 MXFP4，需先做块缩放再打包，反量化在接收端做，端到端多出一次格式往返，在 NVLink 5 的高带宽下这部分延迟仍不可忽略。工程判断是：跨卡段一律 MXFP8，卡内段才允许 MXFP4，把“格式切换”限制在单卡内，使通信路径上的数据类型单一。这条规则同时解释了为什么跨卡大模型档位把格式上限压到 MXFP8——不是算力不够，而是通信与反量化的复合开销吃掉了 FP4 的增益。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-28\">二十八 · 量化方案：档位表 + 兜底通道的可复现流程</h3>\n<p>可复现的量化配方由三张表构成：敏感度排序表、档位映射表、兜底通道表。敏感度排序按输出误差逐层测，排序结果写入层元数据；档位映射把排序前若干层钉在 FP8，其余按块打包为 MXFP4，中间带按 MXFP6 过渡；兜底通道表记录每层保留的少量 FP8 通道，用于块缩放对极端 outlier 溢出时的回退。核心打包公式沿用块缩放：</p>\n<div class=\"formula\">$$w_i=\\hat{w}_i\\cdot 2^{e_{\\text{block}}},\\qquad e_{\\text{block}}=\\max_j \\lfloor \\log_2|w_j|\\rfloor$$</div>\n<p>其中 32 元素块的共享指数让块内动态范围对齐，离群值只影响本块尾数精度而不污染整层缩放。推理时按层元数据选 MMA 精度通路，激活按块在线量化，累加器统一 FP32，末端反量化回 BF16 送 VAE。这里的关键工程约束是：反量化必须发生在 VAE 之前而非每个 GEMM 之后，否则 FP32 累加器到 BF16 的往返次数随层数线性增长，显存带宽被反量化流量吃掉。显存侧收益是直接的——低精度权重与激活使中间激活缓存占用下降，同卡可容纳更大 batch，这正是 KV 策略的杠杆来源。</p>\n<p>可复现性要求校准集覆盖目标分辨率与提示分布，换模型或换分辨率必须重跑排序，否则档位失配会把敏感层误压到 FP4。配方文档应记录校准集的分辨率桶、提示采样规则与排序脚本版本，使重跑可审计。代价是校准成本随层数增长，层数越多调优越重，这是规模上限的直接来源。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-29\">二十九 · KV 策略：中间激活缓存的容量与复用</h3>\n<p>DiT 推理的“KV”指单步前向中的中间激活缓存，不是自回归 KV cache。低精度化后其显存占用下降，配方应把这部分节省显式转化为 batch 上限而非闲置。做法是：按层记录激活张量的形状与格式，估算峰值占用 <span>M_peak = Σ_l (H_l·W_l·C_l·b_l)</span>，其中 <span>b_l</span> 为该层格式的字节宽度；MXFP4 层按 0.5 字节/元素计，FP8 层按 1 字节计，BF16 衔接层按 2 字节计。峰值出现在注意力与 FFN 交界处，配方应把 batch 上限卡在这个峰值上，而不是按权重占用估算。</p>\n<p>复用策略上，同一 batch 内不同 latent 若共享提示条件，条件嵌入可只算一次并广播，减少一次前向中的激活写入；但跨步复用需要谨慎——扩散步间的激活分布漂移会让低精度缓存的误差累积，配方应规定缓存只在同一步内复用，跨步一律重算。调度参数与此耦合：连续批处理下新请求插入会打断激活复用窗口，因此批调度器应把“格式切换点”作为不可抢占边界，避免在 MXFP4 段中间插入新请求导致 kernel 重编译。吞吐代价体现在插入延迟上，低延迟档位应关闭段内抢占。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-30\">三十 · 调度参数：batch、段边界与失败模式兜底</h3>\n<p>调度参数表至少包含四项：batch 上下限、段边界抢占策略、格式切换的预热预算、兜底通道触发阈值。batch 上下限由峰值激活占用与 SLO 共同决定，单图端到端时延为 SLO 时，batch 取 1–8 区间内使 GPU 利用率与排队延迟平衡的点；段边界抢占策略规定格式变化处不可插入新请求；预热预算指首次遇到新格式组合时的 kernel 编译开销，配方应把常用格式组合在服务启动时全部预热，避免首请求抖动；兜底阈值指块缩放溢出检测的触发条件，触发后该层临时走 FP8 通道并在元数据中标记，供后续校准复检。</p>\n<p>失败模式兜底要写进调度器而非只写进文档：分布外提示触发 outlier 溢出时，块缩放失效会引起数值异常，调度器应在输出端做一次 BF16 反量化后的范围检查，超阈值则回退该请求到 FP8 全通道重算。这条路径的延迟代价是一次重算，但避免了画质退化扩散到整批。多格式 kernel 分支未融合时，小 batch 下开销占比更高，配方应设 batch 下限并在低于下限时自动降档到统一 MXFP8，用格式统一换调度连续性——这是把“碎片化”从不可控变成可控开关的具体机制。</p>\n<p>最后落在工程判断上：这套配方的可复现性不取决于选了哪个框架，而取决于三张表是否与硬件档位、并行拓扑、KV 峰值一一对应。档位表决定格式上限，拓扑决定格式边界与通信数据类型，KV 峰值决定 batch 上下限，调度参数只在这三者划定的空间内做取舍。任何一项改动——换卡型、改 TP 宽度、换分辨率——都必须触发敏感度重跑与峰值重估，否则配方退化为一次性调参记录而非可复现部署方案。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-31\">三十一 · 配方失效的四个断点与代价账</h3>\n<p>这套配方在纸面上是“敏感层保 FP8、其余层吃 MXFP4”，但真正决定线上成败的不是档位分配本身，而是四个断点：校准集覆盖、kernel 分支融合度、batch 形态、以及末端反量化的位置。校准集必须覆盖目标分辨率与提示分布；换模型或换分辨率不重跑敏感度排序，档位就会失配——被判低敏感的层被压到 MXFP4，而它在新区间上的输出误差实际放大，画质退化会以结构性伪影的形式出现，而不是均匀的噪声上升。误差账可以写成 <div class=\"formula\">$$\\text{Err}\\approx\\sum_{l}\\mathbb{1}[l\\in\\text{sens}]\\,\\epsilon_{\\text{FP8}}+\\mathbb{1}[l\\notin\\text{sens}]\\,\\epsilon_{\\text{MXFP4}}$$</div> 这个式子的工程含义是：总误差由敏感层集合的划分质量主导，而非由平均位宽主导。因此校准不是一次性仪式，而是随服务分布漂移需要重跑的运维项，其成本随层数线性增长，层数越多调优越重，这也是规模上限受校准成本约束的直接原因。</p>\n<p>第二个断点是 kernel 碎片化。多格式混合让同一张计算图里出现 FP8 与 MXFP4 两条 MMA 精度通路，按层元数据切换意味着分支变多；若这些分支未在同一 kernel 内融合，调度器在每个层边界都要做一次通路切换与流水线排空，实际吞吐低于理论值。这个开销在<b>小 batch 下占比更高</b>：批大小按显存与 SLO 取 1–8，单步前向的批量 latent 生成本来就难以把 GEMM 喂满，切换开销摊不薄。于是出现一个反直觉的边界——配方的收益在大 batch 服务化场景最明显，而在低延迟单图请求上，30–50% 的时延下降可能被分支开销吃掉相当一部分。判断标准很直接：若单步前向中主体 GEMM 占比高、VAE 解码占比小，配方成立；若 VAE 或后处理占比上升，混合精度的收益被稀释。</p>\n<p>第三个断点是数值兜底。32 元素块的共享指数 <div class=\"formula\">$$e_{\\text{block}}=\\max_j \\lfloor \\log_2|w_j|\\rfloor$$</div> 让块内动态范围对齐，对离群值比 per-tensor 量化稳，但对<b>极端 outlier 仍可能溢出</b>：块内最大值决定了指数，其余元素被压到很窄的尾数区间，一旦校准集分布过窄、分布外提示触发更强激活，块缩放失效会引起数值异常而非渐进退化。工程上必须保留少量 FP8 通道兜底，代价是这些通道不吃 FP4 吞吐，等于在配方里预留了一小块“高精度税”。同理，末端必须反量化回 BF16 再送 VAE，否则解码漂移会在像素域放大；这一步的代价是一次额外的格式转换与一段 BF16 带宽占用，在显存带宽紧张的档位上不可忽略。</p>\n<p>把代价落到配置表上，可复现的思路是按硬件档位定并行拓扑、按校准结果定格式表、按 SLO 定批与调度：单卡为主、大模型走张量并行；KV 指中间激活缓存，低精度后显存占用下降可容纳更大 batch，但 batch 上限仍由 SLO 的单图端到端时延倒推。下表给出配方边界与对应代价的判断口径。<table class=\"mini\"><thead><tr><th>边界条件</th><th>失效表现</th><th>系统代价</th></tr></thead><tbody><tr><td>换模型/分辨率未重校准</td><td>敏感层误压 MXFP4，结构性伪影</td><td>重跑校准，成本随层数增长</td></tr><tr><td>kernel 分支未融合</td><td>吞吐低于理论值</td><td>小 batch 下切换开销占比高</td></tr><tr><td>校准集分布过窄</td><td>outlier 溢出，数值异常</td><td>预留 FP8 兜底通道，损失部分 FP4 吞吐</td></tr><tr><td>VAE 解码占比上升</td><td>端到端收益被稀释</td><td>末端反量化 BF16 带宽开销</td></tr></tbody></table>配方的稳定性不来自格式本身，而来自“格式表 + 兜底通道 + 融合 kernel”三者的联合调优；任何一项缺位，30–50% 的时延收益都会在真实负载上打折。</p>\n<h3 id=\"alg-mx-mixed-precision-dit-sec-32\">三十二 · 显存账本：从权重驻留到激活峰值</h3>\n<p>混合精度分块对显存的改变不是均匀缩放，而是按层分档后的非对称收缩。设第 $l$ 层权重元素数为 $N_l$，格式位宽为 $b_l\\in\\{4,6,8\\}$，则该层权重字节数约为 $N_l b_l/8$ 加上每 32 元素块一个共享指数的开销。块缩放元数据的量级是 $N_l/32$ 个指数项，相对权重本体很小，但在 MXFP4 档位上不可忽略：4 bit 尾数配 8 bit 指数，元数据占比接近 1/4 的位宽膨胀。因此实际驻留显存要写成</p>\n<div class=\"formula\">$$M_{\\text{w}}=\\sum_{l}\\left(\\frac{N_l b_l}{8}+\\frac{N_l}{32}\\cdot s\\right),\\quad s=\\text{指数与对齐填充字节}$$</div>\n<p>敏感层保 FP8、其余走 MXFP4 的分配，使总权重显存落在统一 FP8 与统一 FP4 之间，靠近 FP4 一侧——因为 DiT 主体 GEMM 层数占绝对多数，敏感层通常只是少数归一化、调制与末端投影。真正先崩的往往不是权重，而是激活峰值：分块量化要求激活按块在线量化，块边界对齐与 FP32 累加器让中间张量在 MMA 流水线里同时存在低精度副本与高精度累加副本。批大小取 1–8 时，单图 latent 的激活体量随分辨率线性上升，分辨率翻倍即激活翻倍，而权重不变。工程判断是：低分辨率服务化场景显存瓶颈在权重，高分辨率场景瓶颈迅速切换到激活与中间缓存，此时继续压权重档位收益递减。</p>\n<p>具体例子：一个以主体 GEMM 为主的 DiT，权重在统一 FP8 下占据显存主项；改为敏感层 FP8、其余 MXFP4 后，权重项明显下降，腾出的空间被部署配方用于放大 batch。但若分辨率提升一档，激活项增长快于权重项的节省，batch 上限被激活而非权重卡住——这就是规模上去后第一个显存拐点。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-33\">三十三 · 带宽与格式切换：kernel 碎片化的真实代价</h3>\n<p>MX 混合精度的带宽收益来自两处：权重读取字节数按位宽下降，以及块缩放让低精度通路在相同 HBM 事务里搬运更多有效元素。但带宽账不能只看理论位宽比，要扣掉格式切换带来的额外流量。推理时按层元数据选择 MMA 精度通路，意味着同一此前的融合 kernel 被拆成按格式分派的多个分支；分支之间若不能在同一流水线内衔接，就会出现中间结果落回片上或甚至写回 HBM 再读的情况。设层 $l$ 的输出需在格式 $f_l$ 与 $f_{l+1}$ 之间转换，转换代价为一次读写往返，则有效带宽利用率为</p>\n<div class=\"formula\">$$\\eta=\\frac{\\sum_l N_l b_l}{\\sum_l N_l b_l+\\sum_{l\\in\\text{switch}}2N_l b_{\\text{mid}}}$$</div>\n<p>其中 $b_{\\text{mid}}$ 是转换中间格式的位宽。分支越多、相邻层格式差异越大，$\\eta$ 越低。小 batch 下这一项尤其致命：MMA 启动与分支调度的固定开销无法被批量摊薄，实际吞吐低于理论值，而大 batch 能把切换开销摊到更多 token 上。这就是失败模式里“多格式 kernel 分支未融合，调度碎片化使实际吞吐低于理论值”的带宽解释。</p>\n<p>具体例子：敏感层与 MXFP4 层交替排布时，每个交替点都是一次格式切换；若把敏感层集中排布、减少交替次数，切换点数量下降，$\\eta$ 上升。工程上应把敏感度排序结果不仅用于选档位，还用于重排层序或至少合并相邻同格式层，把切换次数压到与敏感层数量同阶而非与层数同阶。代价是重排改变了数值路径，需要重新验证输出误差，这一步不能省。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-34\">三十四 · 通信：张量并行下的格式对齐与集合通信量</h3>\n<p>单卡为主、大模型走张量并行是部署配方的默认拓扑。一旦进入张量并行，混合精度的通信代价出现两个新来源。其一是集合通信的字节数按参与通信的张量位宽计：若 all-reduce 或 all-gather 在 MXFP4 张量上做，通信量按 4 bit 算，看似减半；但块共享指数必须随尾数一起传，否则接收端无法反量化，于是每个 32 元素块附带一个指数项，通信量回升。其二是不同 rank 上同一层的格式必须一致，否则反量化结果无法对齐；敏感度校准是按层做的，若某层在不同 rank 上被判为不同档位，就会出现格式不一致，需要额外的格式协商或强制统一，这直接吃掉了按层分档的自由度。</p>\n<p>设张量并行度为 $P$，某集合通信涉及元素数 $N$、位宽 $b$、块大小 32、指数字节 $s$，则单次通信字节数为</p>\n<div class=\"formula\">$$B_{\\text{comm}}=P\\cdot\\left(\\frac{Nb}{8}+\\frac{N}{32}s\\right)$$</div>\n<p>NVLink 5 的高带宽让这项在小 $P$ 下不显眼，但 $P$ 增大后通信量与格式元数据同步开销同步上升。规模上去后第二个崩点就在这里：不是单卡算不动，而是格式对齐迫使通信从“纯低精度搬运”退化为“低精度加元数据加协商”，有效通信带宽利用率下降。工程判断是：张量并行度应控制在格式切换与元数据开销可摊薄的范围内，敏感层尽量落在不参与切分的维度上，减少跨 rank 的格式分歧。</p>\n<p>具体例子：一个大模型 DiT 在 $P=2$ 时通信开销尚可被计算掩盖；升到更高并行度后，每层 all-reduce 都携带块指数，通信时间占比上升，且格式协商在启动阶段引入额外同步。此时把敏感层集中到单个 rank 或复制到各 rank 以避免切分，反而比追求均匀切分更省——这是通信账倒逼的拓扑选择。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-35\">三十五 · 功耗与频率：低精度通路的能效非线性</h3>\n<p>MXFP4 的吞吐优势在功耗维度不是线性的。位宽减半降低的是数据搬运能量与 MMA 阵列的开关活动，但块缩放、格式分派、FP32 累加器这些周边电路在低精度档位上并不按比例缩小。敏感层保 FP8 意味着这些层仍以较高位宽运行，其功耗密度高于 MXFP4 层；混合部署下整卡功耗是各层功耗的加权和，权重是各层运行时间占比。设层 $l$ 的功耗为 $p_l$、运行时间占比为 $\\tau_l$，则平均功耗为</p>\n<div class=\"formula\">$$P_{\\text{avg}}=\\sum_l \\tau_l p_l,\\quad \\sum_l\\tau_l=1$$</div>\n<p>由于敏感层通常计算量小但位宽高，$\\tau_l$ 小、$p_l$ 大，对平均功耗贡献有限；MXFP4 层 $\\tau_l$ 大、$p_l$ 小，是节能主项。真正的功耗风险在格式切换点：分支调度与格式转换让 SM 在短时间内频繁切换工作模式，频率与电压调节跟不上，出现局部功耗尖峰。规模上去后，功耗先崩的地方不是稳态平均功耗，而是切换密集区的瞬态。工程上减少交替次数不仅省带宽，也平抑功耗尖峰。</p>\n<p>具体例子：连续多个 MXFP4 层构成的长段让 SM 稳定在低精度高能效状态；一段敏感层插入后，SM 切到 FP8 通路，功耗密度跳升。若这种交替在时间上密集，功耗管理单元来不及平滑，整卡功耗上限被瞬态顶到，触发降频，反而拖低吞吐。把敏感层集中成段、减少交替，是功耗与带宽共同的优化方向。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-36\">三十六 · 尾延迟：小 batch 与分布外提示的双重放大</h3>\n<p>SLO 以单图端到端时延计，尾延迟决定服务是否达标。混合精度分块对尾延迟的贡献有两个放大机制。第一是小 batch 下的固定开销占比：batch 取 1–8，MMA 启动、格式分派、块量化对齐都是与批量无关的固定成本，batch 越小，这些成本在端到端时延里占比越高。设单步固定开销为 $c_0$、与批量成正比的计算时间为 $c_1 B$，则单图时延近似为</p>\n<div class=\"formula\">$$T(B)=\\frac{c_0+c_1 B}{B}=c_1+\\frac{c_0}{B}$$</div>\n<p>$B$ 越小，$c_0/B$ 越大，尾延迟越差。第二是分布外提示触发的数值异常：校准集分布过窄时，被判低敏感的层在分布外输入上实际误差放大，块缩放对极端 outlier 溢出，触发兜底 FP8 通道或反量化重算，这条慢路径只在少数请求上出现，却把尾延迟拉长。尾延迟的分布因此是双峰的：多数请求走快路径，少数请求因数值兜底走慢路径。</p>\n<p>具体例子：一个服务在 batch=1 时单图时延被固定开销主导，放大 batch 后均值下降但尾延迟由分布外请求决定；某条提示触发敏感层误判与块溢出，末端反量化回 BF16 送 VAE 前多了一次数值修正，端到端时延明显高于同批其他请求。工程判断是：尾延迟治理要同时压固定开销（融合分支、减少切换）和压慢路径触发率（扩大校准集覆盖、保留少量 FP8 兜底通道但限制其触发频率），两者缺一不可。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-37\">三十七 · 规模上去以后哪里先崩：拐点排序</h3>\n<p>把五本账放在一起，规模上升时各资源的紧张顺序并不一致，取决于负载形态。低分辨率、主体 GEMM 占主导的服务化场景，权重显存先松后紧、激活显存随分辨率先崩；batch 放大到一定程度后，格式切换的带宽与功耗尖峰成为第二拐点；进入张量并行后，格式对齐的通信开销成为第三拐点；尾延迟则始终由小 batch 固定开销与分布外慢路径两条线拉扯，不随规模单调改善。校准成本与 kernel 分支数是规模上限的软约束：层数越多，敏感度排序与调优越重，换模型或换分辨率必须重跑，否则档位失配让敏感层被误压到 FP4，画质退化直接反映为返工与重试，反过来推高有效尾延迟。</p>\n<table class=\"mini\"><thead><tr><th>资源</th><th>先崩条件</th><th>主导机制</th><th>工程动作</th></tr></thead><tbody><tr><td>权重显存</td><td>低分辨率、大模型</td><td>位宽分档后的驻留量</td><td>敏感层集中、其余压 MXFP4</td></tr><tr><td>激活显存</td><td>分辨率提升</td><td>在线量化副本与 FP32 累加</td><td>控 batch、分块调度</td></tr><tr><td>带宽</td><td>格式交替密集、小 batch</td><td>切换往返与分支碎片</td><td>合并同格式层、融合分支</td></tr><tr><td>通信</td><td>张量并行度上升</td><td>块指数随尾数传输、格式协商</td><td>限并行度、敏感层不切分</td></tr><tr><td>功耗</td><td>切换密集区</td><td>瞬态功耗尖峰触发降频</td><td>敏感层成段、减少交替</td></tr><tr><td>尾延迟</td><td>batch=1、分布外提示</td><td>固定开销占比与数值兜底慢路径</td><td>扩校准集、限兜底触发</td></tr></tbody></table>\n<p>拐点排序的工程含义是：不要用单一指标判断扩容是否划算。权重省下来的显存若被激活吃掉，放大 batch 的收益就被抵消；带宽与功耗的改善依赖层序重排，而层序重排又要重新校准验证。真正决定规模上限的是“格式切换次数 × 校准重跑成本”这个乘积——它同时约束 kernel 分支数与数值可信度，是混合精度分块在 Blackwell 上从单卡走向更大拓扑时最先触顶的软资源。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-38\">三十八 · 混合精度分块撞上系统墙：从显存账本到尾延迟的失效边界</h3>\n<p>单卡跑通不等于规模可用。MX 混合精度把权重按 32 元素块打包成 MXFP4/MXFP6/MXFP8 三种格式后，显存账本要按层重算：设第 <i>l</i> 层权重元素数为 <i>N<sub>l</sub></i>，位宽为 <i>b<sub>l</sub></i>∈{4,6,8}，则该层权重字节数为 <i>N<sub>l</sub></i>·<i>b<sub>l</sub></i>/8 再加每 32 元素一个共享指数的开销。敏感层保 FP8 意味着这些层的权重占用是 FP4 层的两倍，若敏感层集中在 attention 投影或 cross-attn 上，显存节省会明显低于“全 FP4”的理论值。低精度后中间激活缓存（KV 意义上的 latent 缓存）占用下降，batch 可从 1 提到 4–8，但每提升一档 batch，单步前向的激活带宽与 MMA 占用同步上升，显存换吞吐的兑换率在 batch 超过某个点后迅速衰减。</p>\n<p>带宽与通信是第二个崩点。DiT 单步前向以 GEMM 为主，MX 格式的收益来自权重读取带宽下降，但 kernel 内格式切换引入额外分支：同一 kernel 里 FP8 通路与 FP4 通路共存时，warp 调度与 TMEM 分配被切成碎片，小 batch 下分支开销占比更高，实际吞吐低于理论值。大模型走张量并行时，每层输出需 all-reduce，混合精度层与 FP8 层的通信量不一致，若不做通信与计算重叠，NVLink 5 上的集合通信会成为尾延迟主因；层数越多，格式切换点越多，重叠窗口越难对齐。</p>\n<p>功耗与尾延迟在服务化场景里最先暴露。SLO 以单图端到端时延计，VAE 解码占比小的场景才适合这套方案；末端反量化回 BF16 送 VAE 的那一段是固定开销，batch 越大摊得越薄，batch=1 时它直接吃掉时延预算。校准集分布过窄时，分布外提示触发 outlier 溢出，块缩放失效引起数值异常，表现为个别请求的画质塌陷而非整体退化——这类尾延迟与尾质量故障最难在压测中复现。规模上限由校准成本与 kernel 分支数共同约束：换模型或换分辨率必须重跑敏感度排序，否则敏感层被误压到 FP4，画质明显退化；层数越多，调优越重，多格式 kernel 未融合时调度碎片化使实际吞吐低于理论值。工程判断是：先确认 DiT 主体 GEMM 占主导、VAE 占比小，再把敏感层清单与 kernel 融合度作为扩容前置条件，否则 30–50% 的时延收益会在规模上去后被通信与分支开销吃掉。</p>\n<h3 id=\"alg-mx-mixed-precision-dit-sec-39\">三十九 · 敏感层被误压到 FP4：校准失配的静默退化</h3>\n<p>MX 混合精度分块最危险的失败不是崩溃，而是“看起来正常”的画质漂移。机制上，档位分配完全由校准阶段逐层测得的输出误差排序决定：<span class=\"inline-formula\">$\\hat{W}_{b}=\\text{shared\\_exp}_{b}\\cdot Q_{p}(W_{b})$</span>，敏感层走 FP8、其余走 MXFP4。一旦换模型或换分辨率却没有重跑敏感度排序，排序结果与真实敏感层错位，本该保 FP8 的层被压到 MXFP4，误差沿残差主干逐层累积，末端反量化回 BF16 送 VAE 也无法挽回——漂移发生在 VAE 之前。</p>\n<p>诊断的关键是把“层敏感度”变成可观测指标，而不是只在离线校准表里存在。工程做法是在推理路径上挂轻量探针：对每个被判定为低敏感的层，周期性抽取其输出张量与 BF16 参考路径（或上一版量化版本的缓存输出）做相对误差统计，按 <span class=\"inline-formula\">$\\text{Err}\\approx\\sum_{l}\\mathbb{1}[l\\in\\text{sens}]\\,\\epsilon_{\\text{FP8}}+\\mathbb{1}[l\\notin\\text{sens}]\\,\\epsilon_{\\text{MXFP4}}$</span> 的分解思路归因到具体层号。代价是探针本身占用带宽与少量算力，在单卡 DiT 前向里表现为单步时延的可测上浮，因此探针应采样而非全量开启，且只在灰度批次上跑。</p>\n<p>具体例子：同一模型从 1024 分辨率切到 2048，patch 数与激活动态范围同时变化，原校准集若只覆盖 1024，块共享指数 <span class=\"inline-formula\">$e_{\\text{block}}=\\max_j\\lfloor\\log_2|w_j|\\rfloor$</span> 在高分辨率激活下的分布偏移会让若干层实际误差放大数倍，而离线表仍标记为低敏感。判据是：灰度批次的探针误差超过阈值即触发档位回滚，把该层从 MXFP4 升回 FP8，而不是整模型回退。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-40\">四十 · OOM：激活缓存与批边界的耦合</h3>\n<p>DiT 推理的显存压力不在权重而在中间激活缓存——低精度量化让权重占用下降，腾出的空间被调度器立刻用于放大 batch，于是 OOM 往往发生在“量化成功之后”。机制上，激活按块在线量化、累加器统一 FP32，意味着每个 MMA 通路的累加缓冲按 FP32 计，格式切换越频繁，同时驻留的中间张量种类越多；多格式混合让 kernel 分支变多，分支各自的 workspace 叠加是隐性显存开销。</p>\n<p>诊断路径是把显存拆成三段独立监控：权重与元数据（层档位表、共享指数）、激活缓存（按 batch 与分辨率线性增长）、kernel workspace（按分支数而非 batch 增长）。前两段随 batch 变化，第三段不随 batch 变化却在多格式下显著。工程判断是：当 OOM 发生在小 batch 而大 batch 反而稳定时，问题几乎必然在 workspace 与分支碎片，而非激活。</p>\n<p>回滚策略不是降精度而是降并发：先把 batch 从上限往下压一档，观察 workspace 段是否释放；若释放不明显，则把相邻的若干 MXFP6 层合并到同一格式以减少分支数，牺牲少量吞吐换显存确定性。代价明确——分支合并会让原本吃 FP4 吞吐的层退回 FP8 通路，整体时延上浮，但换来的是可预测的显存上界。具体例子：批大小按显存与 SLO 取 1–8 的区间内，若 8 触发 OOM 而 6 稳定，应固定 6 并把剩余显存留给激活缓存而非继续试探 7。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-41\">四十一 · 批抖动与路由不均：调度层的两类噪声</h3>\n<p>批抖动指相邻批次的端到端时延方差异常放大，根因通常在格式切换的调度碎片化：多格式 kernel 分支未融合时，同一 batch 内不同层走不同 MMA 精度通路，SM 上的常驻 block 数随层序反复变化，小 batch 下固定开销占比更高，于是时延不再随 batch 单调。诊断方法是按层记录 kernel 启动与结束时间戳，画出单步前向的“格式时间线”；若时间线上出现密集的短分支交替，即为碎片化证据。</p>\n<p>路由不均则是另一类问题：张量并行下各 rank 分到的层档位不同，FP8 层与 MXFP4 层的算力需求不对称，导致 rank 间等待。机制上敏感层保 FP8 是逐层决策，若层切分恰好把多个 FP8 敏感层集中到同一 rank，该 rank 成为瓶颈，其余 rank 空转。监控指标应是每 rank 的 MMA 占用率与 all-reduce 等待时长之比，而非全局吞吐——全局吞吐会被快 rank 掩盖。</p>\n<p>回滚手段是重排层到 rank 的映射，把 FP8 敏感层在 rank 间均匀摊开，代价是引入额外的通信跳数或改变切分点，可能牺牲少量并行效率。具体例子：单卡为主、大模型走张量并行的拓扑下，若某 rank 持续高占用而其他 rank 等待，优先调整切分边界而非降低整体精度档位，因为后者会同时伤害所有 rank 的画质。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-42\">四十二 · 尾延迟尖刺：outlier 溢出与兜底通道</h3>\n<p>块缩放对离群值比 per-tensor 量化鲁棒，但对极端 outlier 仍可能溢出：32 元素块的共享指数被块内最大值拉高，块内小值被压到接近零，量化尾数有效位不足，数值异常表现为偶发的尾延迟尖刺——不是每张图都慢，而是特定提示触发的少数批次慢。诊断上要把尾延迟与提示特征关联：统计 P99 时延批次的激活块最大绝对值分布，若显著高于 P50 批次，即为 outlier 触发。</p>\n<p>机制层面的兜底是保留少量 FP8 通道：当在线量化的块最大绝对值超过预设阈值时，该块临时走 FP8 通路而非 MXFP4，避免溢出。代价是这条兜底路径让 kernel 分支进一步增多，编译与调优成本上升，且兜底触发率本身是监控对象——触发率过高说明校准集分布过窄，需要扩充而非继续加兜底。</p>\n<p>具体例子：校准集需覆盖目标分辨率与提示分布，若线上提示分布外移，被判低敏感的层实际误差放大，尾延迟与画质退化同时出现。工程判断是把“兜底触发率”和“探针误差”作为一对联合指标：前者高说明数值路径在救火，后者高说明救火没救住，此时唯一正确的动作是重跑敏感度校准并重新分配档位，而不是在推理侧继续调阈值。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-43\">四十三 · 监控面与回滚分级</h3>\n<p>监控面应覆盖四层：层档位元数据的一致性（校准版本与模型/分辨率是否匹配）、探针误差（按层归因）、显存三段分解、以及每 rank 的占用与等待。前两项对应精度失败，后两项对应 OOM 与路由不均。指标采集频率与采样率需与 SLO 挂钩：单图端到端时延计费的场景下，全量探针不可接受，采样率应按灰度流量比例设定。</p>\n<p>回滚必须分级而非一刀切，因为 MX 混合精度的价值正在于“按层分配”，整模型回退等于放弃 30–50% 的时延收益。分级顺序建议为：单层档位回滚（FP4→FP8）→ 分支合并（减少格式种类）→ batch 下调 → 整模型回退到统一 FP8。每一级都有明确的触发条件与代价标签，避免值班工程师在尾延迟尖刺时直接跳到最重的一级。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首要观测</th><th>回滚动作</th><th>代价</th></tr></thead><tbody><tr><td>敏感层误压 FP4</td><td>按层探针误差</td><td>单层升回 FP8</td><td>该层吞吐下降</td></tr><tr><td>OOM</td><td>workspace 段显存</td><td>合并格式分支 / 降 batch</td><td>时延上浮</td></tr><tr><td>批抖动</td><td>格式时间线碎片</td><td>融合相邻分支</td><td>编译成本</td></tr><tr><td>路由不均</td><td>rank 占用/等待比</td><td>重排层到 rank 映射</td><td>通信跳数</td></tr><tr><td>尾延迟尖刺</td><td>兜底触发率 + 探针误差</td><td>重跑敏感度校准</td><td>校准成本</td></tr></tbody></table>\n<p>这张表的用法是把它绑到发布流程上：每次换模型或换分辨率，校准版本号必须与部署配置一同进入灰度，版本不匹配直接拒绝上线，从源头掐掉第一类失败。规模上限受校准成本与 kernel 分支数约束，层数越多调优越重，因此监控面的自动化程度决定了这套混合精度能否长期维持——人工比对层档位表在几十层规模下尚可，在上百层规模下必然失守。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-44\">四十四 · 失效边界：校准失配、kernel 碎片与尾延迟的三类现场</h3>\n<p>这套按层分档的 MX 混合精度方案，真正的风险不在稳态吞吐，而在“档位分配”与“运行时实际数据分布”之间的错位。核心公式给出误差上界：<div class=\"formula\">$$\\text{Err}\\approx\\sum_{l}\\mathbb{1}[l\\in\\text{sens}]\\,\\epsilon_{\\text{FP8}}+\\mathbb{1}[l\\notin\\text{sens}]\\,\\epsilon_{\\text{MXFP4}}$$</div>它把总误差拆成敏感层与非敏感层两部分，但前提是集合 <em>sens</em> 本身判对了。一旦换模型或换分辨率而未重跑逐层敏感度排序，原本被判低敏感的层被压到 MXFP4，公式第二项就会在错误的位置上放大——画质退化不是均匀变糊，而是特定结构（高频纹理、细边缘）出现块状伪影。诊断上不要只看整图 PSNR，应按层记录输出误差排序与量化前后的激活直方图，把“档位分配表”和“实际误差贡献”做逐层对齐；偏差集中在少数层时，说明校准集覆盖不足，而非格式本身失效。</p>\n<p>第二类失效是 kernel 碎片化。多格式混合让同一张计算图里并存 FP8 与 MXFP4 两条 MMA 通路，若分支未融合，调度器在每个层边界都要做格式切换与元数据查表，小 batch 下这部分固定开销占比陡增。代价可直接估：设单层切换开销为 <em>c</em>，层数为 <em>L</em>，则每步额外时延约 <em>c·L</em>，与 GEMM 主体时间无关，因此 batch=1–2 时吞吐可能明显低于理论值，而 batch 增大后又被摊薄——这正是“批抖动”的来源：批大小在 1–8 间波动时，端到端时延不随 batch 线性变化，SLO 以单图时延计时会出现尖刺。监控应把每层 MMA 通路的实际占用时间、格式切换次数、以及 batch 与 P99 时延的联合分布画在一起，尖刺若与切换次数同相位，就是碎片化而非算力不足。</p>\n<p>第三类是数值侧的块缩放失效。32 元素共享指数 <em>e</em><sub>block</sub> 取块内最大幅值对齐，对常规离群值鲁棒，但极端 outlier 仍可能让尾数溢出或让同块内小值被压到零。校准集分布过窄时，分布外提示触发的激活 outlier 会绕过校准阶段的统计，表现为个别 step 输出 NaN 或色偏。工程兜底是保留少量 FP8 通道：对误差贡献排名靠前且方差大的层强制走 FP8，其余才走 MXFP4，并在运行时对块缩放后的尾数做溢出计数，超阈值即触发该层回退。回滚粒度必须是“层级”而非“模型级”——整模型退回 BF16 会丢掉全部 30–50% 的时延收益，而层级回滚只损失单层吞吐。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>代价落点</th><th>处置</th></tr></thead><tbody><tr><td>校准失配</td><td>逐层误差贡献偏离档位表</td><td>画质退化，非时延</td><td>重跑敏感度排序</td></tr><tr><td>kernel 碎片</td><td>切换次数与 P99 同相位</td><td>小 batch 吞吐、尾延迟</td><td>融合分支或调 batch 下限</td></tr><tr><td>outlier 溢出</td><td>块尾数溢出计数、NaN</td><td>单步数值异常</td><td>层级回退 FP8 兜底</td></tr></tbody></table>\n<p>监控的最小集合应包含三项：每层 MMA 精度通路的实际时延占比、块缩放溢出计数、以及 batch 与端到端时延的联合分位。回滚策略按代价排序：先调 batch 下限压住碎片开销，再对溢出层做 FP8 兜底，最后才考虑重跑校准。注意校准成本本身是规模上限——层数越多、分辨率档位越多，重跑越重，因此换分辨率时必须把敏感度排序纳入发布流水线，而不是当作一次性离线步骤。</p>\n<h3 id=\"alg-mx-mixed-precision-dit-sec-45\">四十五 · 对照轴：把“选谁”拆成四个可判定维度</h3>\n<p>同族算法之间的取舍，不能停在“哪个更快”这种笼统判断上。对 MX 混合精度分块而言，真正决定选型的只有四个可观测维度：敏感层的存在性与分布、GEMM 在端到端时延中的占比、校准预算（能否为每个目标分辨率重跑逐层敏感度排序）、以及 kernel 分支的可承受度。前三个维度决定“值不值得分档”，第四个决定“分档之后能不能兑现”。把这四个维度做成判定轴，相邻算法才落在同一张坐标系里，而不是各自讲各自的优点。</p>\n<p>第一个维度用敏感度集中度刻画。设逐层输出误差排序后，前 $k$ 层贡献的误差占比为 $\\rho_k$，则</p>\n<div class=\"formula\">$$\\rho_k=\\frac{\\sum_{l\\in \\text{top-}k}\\epsilon_l}{\\sum_{l}\\epsilon_l},\\qquad \\text{Split}=\\mathbb{1}[\\rho_{k^{*}}\\ge \\theta]$$</div>\n<p>当 $\\rho$ 在很小的 $k^{*}$ 上就越过阈值 $\\theta$，说明误差高度集中在少数层，分档收益大；若 $\\rho$ 随层数近似线性上升，说明误差均匀铺开，按层分档的边际收益被 kernel 碎片化吃掉。这个判据不需要绝对误差数值，只需要排序后的相对分布，因此换模型时可以直接复用校准流程的输出。</p>\n<p>第二个维度是 GEMM 占比。DiT 单步前向里，主体 GEMM 与注意力占大头、VAE 解码占比小的服务化形态，才是 MX 分档的主场；若 VAE 解码或后处理在端到端时延中不可忽略，末端反量化回 BF16 的那一段就会稀释掉 FP4 通道省下的时间。第三个维度是校准预算：换分辨率必须重跑敏感度排序，多分辨率服务意味着校准成本按分辨率数量线性叠加。第四个维度是分支数：格式档位每多一档，kernel 内精度通路切换的分支就多一组，编译与调优成本上升，小 batch 下调度开销占比更高。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-46\">四十六 · 决策表：五种相邻路线在同一张表上比较</h3>\n<p>把统一 FP8、统一 NVFP4、per-tensor 低比特、特征缓存跳步、以及本条的 MX 按层混合放在一起，按上述四轴给出适用条件。表中不写绝对吞吐数字，只写判定条件与代价落点，避免把不同实验设置下的数字混为一谈。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>路线</th><th>敏感层处理</th><th>GEMM 占比要求</th><th>校准预算</th><th>主要代价落点</th><th>适用条件</th></tr>\n</thead>\n<tbody>\n<tr><td>统一 FP8</td><td>不区分，全层同精度</td><td>中高</td><td>低（无需逐层排序）</td><td>吃不满 FP4 吞吐，时延收益封顶</td><td>敏感层分布均匀、追求部署简单</td></tr>\n<tr><td>统一 NVFP4</td><td>不区分，全层 FP4</td><td>高</td><td>低</td><td>敏感层画质退化，需靠末端反量化兜底</td><td>画质容忍度高、吞吐优先</td></tr>\n<tr><td>per-tensor 低比特</td><td>不区分，单缩放因子</td><td>中</td><td>低</td><td>离群值拉低整张量有效位宽</td><td>权重分布紧、离群值少</td></tr>\n<tr><td>特征缓存/块级跳步</td><td>不涉及精度分档</td><td>任意</td><td>中（缓存命中率调优）</td><td>跨步一致性、缓存显存占用</td><td>相邻步特征高度相似、少步采样</td></tr>\n<tr><td>MX 按层混合</td><td>敏感层保 FP8，其余 MXFP4</td><td>高（主体 GEMM 主导）</td><td>高（逐层排序，换分辨率重跑）</td><td>kernel 分支碎片化、校准失配风险</td><td>敏感层集中、服务化多分辨率可控</td></tr>\n</tbody>\n</table>\n<p>读表的关键在于两列的耦合：校准预算高而 GEMM 占比低的组合，是 MX 分档最不划算的角落——花大力气做逐层排序，省下的时间却被非 GEMM 段吞掉。反过来，GEMM 占比高但敏感层分布均匀（$\\rho$ 线性上升），则应退回统一 FP8，把工程复杂度留给别处。特征缓存跳步与精度分档不在同一正交轴上，二者可以叠加：跳步减少实际执行的步数，分档降低单步代价，但叠加时要注意缓存命中率对低精度激活数值漂移的敏感性。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-47\">四十七 · 判据伪代码：把选型写成可执行分支</h3>\n<p>选型逻辑应当写成确定性分支，而不是凭经验拍板。下面给出判定顺序，输入是校准阶段已经产出的逐层误差排序、端到端各段时延占比、以及目标分辨率集合。</p>\n<p>伪代码思路：先算 $\\rho_{k^{*}}$ 判断敏感度是否集中；若不集中，直接落到统一 FP8 或统一 NVFP4；若集中，再看 GEMM 时延占比是否越过门槛；越过则进入 MX 分档，并按分辨率数量估算校准重跑成本；最后检查档位数是否超过 kernel 可维护上限，超了就砍掉 MXFP6 这一中间档，只保留 FP8 与 MXFP4 两档。</p>\n<ul>\n<li>分支一：$\\text{Split}=0$ 且画质容忍度高 → 统一 NVFP4，省掉逐层排序。</li>\n<li>分支二：$\\text{Split}=0$ 且画质要求严 → 统一 FP8，接受时延收益封顶。</li>\n<li>分支三：$\\text{Split}=1$ 且 GEMM 占比低于门槛 → 不做精度分档，改投特征缓存或调度侧优化。</li>\n<li>分支四：$\\text{Split}=1$、GEMM 占比过门槛、分辨率集合小 → MX 三档（FP8/MXFP6/MXFP4）。</li>\n<li>分支五：同分支四但分辨率集合大 → MX 两档，压低校准重跑与分支维护成本。</li>\n</ul>\n<p>这套分支的代价可以直接折算：每多一个分辨率，就要多跑一遍逐层敏感度校准，校准本身是前向推理级别的开销，属于一次性但不可省略的工程投入；每多一个格式档位，kernel 内精度通路切换的分支组合数上升，编译时间与调优工作量随之增加，在小 batch 场景下调度碎片化的相对开销更明显。因此分支五不是保守，而是把“校准成本 × 分辨率数”和“分支数 × 调优成本”两项显式计入决策。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-48\">四十八 · 具体例子：一条 1024 分辨率服务链的选型推演</h3>\n<p>设想一条面向 1024 分辨率、批大小按显存与 SLO 取 1–8 的 DiT 服务链，主体 GEMM 与注意力占端到端时延的大头，VAE 解码占比小。校准阶段逐层测敏感度后，误差排序显示少数层贡献了大部分输出误差，$\\rho_{k^{*}}$ 在很小的 $k^{*}$ 上就越过阈值——敏感度集中，分支一、二被排除。</p>\n<p>接着看 GEMM 占比：主体 GEMM 主导，分支三也被排除，进入 MX 分档。此时若该服务只服务单一分辨率，走分支四，三档分配：敏感层保 FP8，中间层用 MXFP6 过渡，其余层走 MXFP4，权重按 32 元素块做共享指数缩放，推理时按层元数据选 MMA 精度通路，激活按块在线量化、累加器统一 FP32，末端反量化回 BF16 送 VAE。若该服务要覆盖多个分辨率，每换一个分辨率都要重跑敏感度排序，否则档位分配失配会把敏感层误压到 FP4，画质明显退化——这正是分支五选择两档的理由：用 MXFP4 与 FP8 两档换取校准与分支的简化。</p>\n<p>这条链上的代价分布很具体：低精度后中间激活缓存占用下降，可容纳更大 batch，吞吐侧受益；但多格式混合让 kernel 分支变多，编译与调优成本高，小 batch 下分支调度开销占比更高，因此批大小取 1 时未必能兑现理论吞吐。校准集必须覆盖目标分辨率与提示分布，分布过窄会让分布外提示触发 outlier 溢出，块缩放失效引起数值异常；工程上保留少量 FP8 通道兜底，正是为了这类溢出场景。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-49\">四十九 · 与统一路线的定量对照：误差项与收益项的分解</h3>\n<p>把本条与统一路线放在同一误差分解下对照，选型判断才有依据。混合分档的总误差可写成按层指示函数的加权和：</p>\n<div class=\"formula\">$$\\text{Err}\\approx\\sum_{l}\\mathbb{1}[l\\in\\text{sens}]\\,\\epsilon_{\\text{FP8}}+\\mathbb{1}[l\\notin\\text{sens}]\\,\\epsilon_{\\text{MXFP4}}$$</div>\n<p>统一 FP8 对应所有层都取 $\\epsilon_{\\text{FP8}}$，误差项最小但吞吐项封顶；统一 NVFP4 对应所有层取 $\\epsilon_{\\text{MXFP4}}$，吞吐项拉满但敏感层误差被放大。混合分档的收益来自把 $\\epsilon_{\\text{MXFP4}}$ 只施加在非敏感层上，代价是要为敏感层保留 FP8 通路，于是整体时延落在两者之间——给定事实给出的量级是整体时延降 30–50%，画质退化可控。这个区间不是无条件成立的：它依赖敏感层确实集中，且 GEMM 占比足够高，否则收益项被非 GEMM 段与分支开销抵消。</p>\n<p>与 per-tensor 量化的对照落在块缩放这一项上。32 元素块共享指数让块内动态范围对齐，$e_{\\text{block}}=\\max_j\\lfloor\\log_2|w_j|\\rfloor$ 只由块内最大幅值决定，离群值只影响所在块而不拉低整张量的有效位宽，因此比 per-tensor 量化稳定；代价是块缩放需要硬件 block scale 路径配合，且极端 outlier 仍可能溢出，需保留 FP8 通道兜底。这一条决定了：权重分布紧、离群值少的模型，per-tensor 量化的部署成本更低，不必上 MX 分档。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-50\">五十 · 工程判断：什么时候不该选 MX 分档</h3>\n<p>选型的最后一层判断是“不选”的条件，比“选”的条件更需要写清楚。第一，敏感层分布均匀时不选：逐层排序做完了却发现 $\\rho$ 线性上升，分档的边际收益被 kernel 碎片化吃掉，此时统一 FP8 的部署简单性更有价值。第二，非 GEMM 段占比不可忽略时不选：末端反量化回 BF16 送 VAE 的那一段若在端到端时延中占比上升，FP4 通道省下的时间被稀释，收益项缩水。第三，多分辨率且校准预算受限时不选三档：每换分辨率必须重跑敏感度排序，档位越多、失配风险越大，两档是更稳的折中。</p>\n<p>第四，小 batch 常态时不选：多格式 kernel 分支未融合会让调度碎片化，小 batch 下开销占比更高，实际吞吐低于理论值，此时应先把分支融合做掉再谈分档。第五，分布外提示占比高的服务不选：校准集分布过窄会让被判低敏感的层在分布外提示上实际误差放大，块缩放对极端 outlier 仍可能溢出，画质退化不可控。这五条合起来指向一个工程判断：MX 分档的收益是“敏感层集中 × GEMM 主导 × 校准可重跑 × 分支可维护”四项同时成立的乘积，任何一项塌陷，都应退回统一路线或改投调度侧优化，而不是靠增加档位去补。</p>\n\n<h3 id=\"alg-mx-mixed-precision-dit-sec-51\">五十一 · 边界、失效条件与选型决策</h3>\n<p>这套按层分档的 MX 混合精度不是通用解，它的收益上限由 DiT 主体 GEMM 在端到端时延中的占比决定。设主体占比为 $\\rho$、敏感层比例为 $s$、非敏感层相对 FP8 的加速比为 $k$，则端到端时延近似为 $T\\approx T_{\\text{base}}\\left[(1-\\rho)+\\rho\\left(s+(1-s)/k\\right)\\right]$，末端反量化回 BF16 送 VAE 的那一段不参与收益分摊。当 VAE 解码与调度开销占比抬升、或 batch 被压到 1 附近时，kernel 内格式切换的固定开销摊不薄，实测吞吐会低于理论值——这正是“多格式分支未融合”这类失败模式的来源。反过来，若服务形态是单卡、批大小 1–8、以单图端到端时延计 SLO，且主体 GEMM 占主导，则 30–50% 的时延下降才有落地空间。</p>\n<p>与相邻算法对照，选择取决于三个可判定的条件，而非精度数字本身：</p>\n<table class=\"mini\"><thead><tr><th>候选方案</th><th>适用条件</th><th>不适用/失效点</th><th>主要系统代价</th></tr></thead><tbody><tr><td>统一 FP8</td><td>层间敏感度差异小、校准预算为零、追求 kernel 单一</td><td>吃不满 FP4 吞吐，主体 GEMM 受限</td><td>吞吐上限低，显存下降有限</td></tr><tr><td>统一 NVFP4</td><td>模型对量化鲁棒、画质容忍度高</td><td>敏感层误差放大，画质退化不可控</td><td>需额外兜底通道</td></tr><tr><td>per-tensor 量化</td><td>权重分布集中、无显著 outlier</td><td>离群值破坏缩放，数值不稳</td><td>精度回退风险</td></tr><tr><td>MX 按层混合</td><td>主体 GEMM 主导、可承担校准、分辨率固定</td><td>换模型/换分辨率未重跑校准即失配</td><td>kernel 分支碎片化，编译调优重</td></tr></tbody></table>\n<p>失效条件要写进上线检查单：换模型或换分辨率必须重跑逐层敏感度排序，否则被判低敏感的层被误压到 MXFP4，画质退化会直接暴露；校准集分布过窄时，分布外提示触发极端 outlier，32 元素块共享指数 $e_{\\text{block}}=\\max_j\\lfloor\\log_2|w_j|\\rfloor$ 仍可能溢出，需保留少量 FP8 通道兜底。规模上限受校准成本与 kernel 分支数双重约束——层数越多，逐层测敏感度与逐格式调优的工程量越重，此时应优先收敛格式档位（例如只保留 MXFP8 与 MXFP4 两档），用少量精度换可维护性。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · 扩散服务化与 SLO 调度</td></tr><tr><td>解决什么</td><td>统一低精度量化对 DiT 的敏感层伤害大，而统一高精度又吃不满 Blackwell 的 FP4/FP8 吞吐，精度与速…</td></tr><tr><td>一句话机制</td><td>按层敏感度分配 MXFP4/MXFP6/MXFP8 混合格式，共享指数做块缩放，敏感层保 FP8、其余走 MXFP4，…</td></tr><tr><td>代价与失效</td><td>多格式混合让 kernel 分支变多，编译与调优成本高；敏感度排序依赖校准集，换模型或换分辨率需重跑</td></tr><tr><td>后继</td><td>特征缓存与动态救援</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-mx-mixed-precision-dit · 共 8 个片段</p>\n";break;}}})();
